// A small regex engine implementing the subset of the Rust `regex`
// crate syntax that dust users rely on. Matching is done with
// position-set (NFA style) evaluation, which keeps it polynomial
// for the patterns we support.
use std::collections::HashSet;

#[derive(Debug, Clone)]
pub struct RegexError {
    pub span_start: usize, // byte index in pattern
    pub span_len: usize,   // in characters (for caret display)
    pub message: String,
}

impl RegexError {
    fn new(start: usize, len: usize, msg: &str) -> Self {
        RegexError { span_start: start, span_len: len.max(1), message: msg.to_string() }
    }
    pub fn render_debug(&self, pattern: &str) -> String {
        let tildes = "~".repeat(79);
        // Build caret line: position in characters
        let chars: Vec<char> = pattern.chars().collect();
        let mut byte_to_char = 0usize;
        let mut caret_col = 0usize;
        for (i, ch) in pattern.char_indices() {
            if i < self.span_start { caret_col += 1; let _ = ch; } else { break; }
        }
        let _ = byte_to_char; byte_to_char = caret_col;
        let mut caret_line = String::new();
        for _ in 0..caret_col { caret_line.push(' '); }
        for _ in 0..self.span_len.max(1) { caret_line.push('^'); }
        let _ = chars;
        format!("Syntax(\n{}\nregex parse error:\n    {}\n    {}\nerror: {}\n{}\n)", tildes, pattern, caret_line, self.message, tildes)
    }
}

#[derive(Debug, Clone, PartialEq)]
enum ClassItem {
    Ch(char),
    Range(char, char),
    Digit(bool), // true = \d, false = \D
    Space(bool),
    Word(bool),
    Posix(String, bool), // name, negated [:^alpha:]
    AnyClass(Box<Class>),
}

#[derive(Debug, Clone, PartialEq)]
struct Class {
    negated: bool,
    items: Vec<ClassItem>,
}

impl Class {
    fn matches(&self, c: char, case_i: bool) -> bool {
        let mut found = false;
        for item in &self.items {
            let m = match item {
                ClassItem::Ch(x) => {
                    if case_i { fold_eq(*x, c) } else { *x == c }
                }
                ClassItem::Range(a, b) => {
                    if case_i {
                        let cl: Vec<char> = c.to_lowercase().collect();
                        let mut ok = false;
                        for cc in cl { if *a <= cc && cc <= *b { ok = true; } }
                        // also consider uppercase of range endpoints
                        ok || (*a <= c && c <= *b)
                    } else { *a <= c && c <= *b }
                }
                ClassItem::Digit(want) => is_digit(c) == *want,
                ClassItem::Space(want) => c.is_whitespace() == *want,
                ClassItem::Word(want) => is_word_char(c) == *want,
                ClassItem::Posix(name, _neg) => posix_matches(name, c),
                ClassItem::AnyClass(inner) => inner.matches(c, case_i),
            };
            if m { found = true; break; }
        }
        if self.negated { !found } else { found }
    }
}

fn fold_eq(a: char, b: char) -> bool {
    if a == b { return true; }
    let mut ai = a.to_lowercase();
    let mut bi = b.to_lowercase();
    ai.next() == bi.next()
}

pub fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}
fn is_digit(c: char) -> bool {
    c.is_numeric() && c.to_digit(10).is_some() || ('\u{660}' <= c && c <= '\u{669}') || c.is_numeric()
}

fn posix_matches(name: &str, c: char) -> bool {
    match name {
        "alpha" => c.is_alphabetic(),
        "digit" => c.is_ascii_digit(),
        "alnum" => c.is_alphanumeric(),
        "space" => c.is_whitespace(),
        "upper" => c.is_uppercase(),
        "lower" => c.is_lowercase(),
        "punct" => c.is_ascii_punctuation(),
        "xdigit" => c.is_ascii_hexdigit(),
        "cntrl" => c.is_control(),
        "blank" => c == ' ' || c == '\t',
        "print" => !c.is_control(),
        "graph" => !c.is_control() && c != ' ',
        "word" => is_word_char(c),
        "ascii" => c.is_ascii(),
        _ => false,
    }
}

#[derive(Debug, Clone, PartialEq)]
enum Ast {
    Empty,
    Char(char),
    Any { nl: bool },
    Class(Class),
    StartText,
    StartLine,
    EndText,
    EndLine,
    WordBoundary(bool), // true = \b, false = \B
    Concat(Vec<Ast>),
    Alt(Vec<Ast>),
    Repeat { node: Box<Ast>, min: u32, max: Option<u32> },
    Group(Box<Ast>),
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct Flags {
    i: bool,
    m: bool,
    s: bool,
    x: bool,
}

impl Default for Flags {
    fn default() -> Self { Flags { i: false, m: false, s: false, x: false } }
}

struct Parser {
    chars: Vec<char>,
    // byte offsets per char index
    pos: usize, // char index
    flags: Flags,
}

impl Parser {
    fn peek(&self) -> Option<char> { self.chars.get(self.pos).copied() }
    fn next(&mut self) -> Option<char> { let c = self.peek(); if c.is_some() { self.pos += 1; } c }
    fn error(&self, char_pos: usize, len: usize, msg: &str) -> RegexError {
        // convert char pos to byte pos
        let byte_pos: usize = self.chars.iter().take(char_pos).map(|c| c.len_utf8()).sum();
        RegexError::new(byte_pos, len, msg)
    }
    fn skip_ws(&mut self) {
        if !self.flags.x { return; }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => { self.pos += 1; }
                Some('#') => {
                    while let Some(c) = self.peek() { if c == '\n' { break; } self.pos += 1; }
                }
                _ => break,
            }
        }
    }

    fn parse_alt(&mut self) -> Result<Ast, RegexError> {
        let mut branches = vec![self.parse_concat()?];
        loop {
            self.skip_ws();
            if self.peek() == Some('|') {
                self.pos += 1;
                branches.push(self.parse_concat()?);
            } else { break; }
        }
        if branches.len() == 1 { Ok(branches.pop().unwrap()) } else { Ok(Ast::Alt(branches)) }
    }

    fn parse_concat(&mut self) -> Result<Ast, RegexError> {
        let mut items = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            let atom = self.parse_atom()?;
            // quantifiers (allow stacking like a**)
            let mut node = atom;
            loop {
                // In verbose mode, whitespace already skipped above; quantifier comes immediately
                match self.peek() {
                    Some('*') => { self.pos += 1; let lazy = self.eat_lazy(); let _ = lazy; node = Ast::Repeat { node: Box::new(node), min: 0, max: None }; }
                    Some('+') => { self.pos += 1; let _ = self.eat_lazy(); node = Ast::Repeat { node: Box::new(node), min: 1, max: None }; }
                    Some('?') => { self.pos += 1; let _ = self.eat_lazy(); node = Ast::Repeat { node: Box::new(node), min: 0, max: Some(1) }; }
                    Some('{') => {
                        // try counted repetition; if it is not a valid counted rep, regex crate errors
                        // except when "{" does not look like a repetition, it may be literal in some modes;
                        // Rust regex requires valid syntax if it starts like a repetition.
                        match self.parse_counted(node.clone())? {
                            Some(n) => { node = n; }
                            None => { break; }
                        }
                    }
                    _ => break,
                }
            }
            items.push(node);
        }
        Ok(Ast::Concat(items))
    }

    fn eat_lazy(&mut self) -> bool {
        if self.peek() == Some('?') { self.pos += 1; true } else { false }
    }

    fn parse_counted(&mut self, node: Ast) -> Result<Option<Ast>, RegexError> {
        // chars[pos] == '{'
        let start = self.pos;
        // Look ahead to decide if this is a counted repetition attempt: {digits or {, etc.
        let rest: String = self.chars.iter().skip(self.pos).collect();
        let is_attempt = {
            let inner = rest.strip_prefix('{').unwrap_or("");
            inner.chars().next().map(|c| c.is_ascii_digit() || c == ',').unwrap_or(false)
        };
        if !is_attempt {
            // In Rust regex, an unescaped "{" that is not a valid counted repetition is an error
            // "repetition quantifier expects a valid decimal" in some cases, but a lone "{" is
            // treated as literal in older versions. Rust regex 1.x: "{" alone is an error
            // (unclosed counted repetition if at end). We follow observed: a{ at end errors.
            // If there is more content and it doesn't look like a count, treat as literal.
            // Determine: if rest is exactly "{" or starts with "{" + non-digit... Observed a{ errors.
            // We'll error unclosed counted repetition when no closing valid content.
            // For simplicity, if no '}' ahead, error; else treat as literal char (handled by caller)
            if !rest.contains('}') {
                return Err(self.error(start, 1, "unclosed counted repetition"));
            }
            return Ok(None);
        }
        // Find closing }
        let mut idx = self.pos + 1;
        let mut content = String::new();
        while idx < self.chars.len() && self.chars[idx] != '}' {
            content.push(self.chars[idx]);
            idx += 1;
        }
        if idx >= self.chars.len() {
            // span from { to end
            return Err(self.error(start, self.chars.len() - start, "unclosed counted repetition"));
        }
        // content is like "2", "2,", "2,5", ",5" (last invalid in Rust regex? {,5} is not allowed)
        let parts: Vec<&str> = content.splitn(2, ',').collect();
        let parse_num = |s: &str, num_start: usize| -> Result<u32, RegexError> {
            if s.is_empty() { return Ok(0); } // handled by caller logic
            match s.parse::<u64>() {
                Ok(v) if v <= u32::MAX as u64 => Ok(v as u32),
                _ => Err(self.error(num_start, s.chars().count(), "decimal literal invalid")),
            }
        };
        // positions: number starts after '{'
        let (min, max) = if parts.len() == 1 {
            if parts[0].is_empty() {
                return Err(self.error(start, idx - start + 1, "repetition quantifier expects a valid decimal"));
            }
            let v = parse_num(parts[0], start + 1)?;
            (v, Some(v))
        } else {
            let min_s = parts[0];
            let max_s = parts[1];
            if min_s.is_empty() {
                return Err(self.error(start, idx - start + 1, "repetition quantifier expects a valid decimal"));
            }
            let minv = parse_num(min_s, start + 1)?;
            if max_s.is_empty() { (minv, None) } else {
                let maxv = parse_num(max_s, start + 1 + min_s.len() + 1)?;
                if minv > maxv {
                    return Err(self.error(start, idx - start + 1, "invalid repetition count range, the start must be <= the end"));
                }
                (minv, Some(maxv))
            }
        };
        self.pos = idx + 1;
        let _ = self.eat_lazy();
        Ok(Some(Ast::Repeat { node: Box::new(node), min, max }))
    }

    fn parse_atom(&mut self) -> Result<Ast, RegexError> {
        self.skip_ws();
        let start = self.pos;
        let c = match self.next() { Some(c) => c, None => return Ok(Ast::Empty) };
        match c {
            '(' => {
                // check group kinds
                if self.peek() == Some('?') {
                    // lookahead on following chars
                    let save = self.pos;
                    self.pos += 1; // '?'
                    match self.peek() {
                        Some('P') => {
                            self.pos += 1;
                            if self.peek() == Some('<') {
                                self.pos += 1;
                                let name = self.parse_group_name(start)?;
                                let inner = self.parse_alt()?;
                                self.expect_close(start)?;
                                let _ = name;
                                return Ok(Ast::Group(Box::new(inner)));
                            } else if self.peek() == Some('=') {
                                // (?P=name) backref - not supported by regex crate
                                return Err(self.error(start, 3, "backreferences are not supported"));
                            } else {
                                return Err(self.error(start, 2, "unrecognized flag"));
                            }
                        }
                        Some('<') => {
                            self.pos += 1;
                            match self.peek() {
                                Some('=') | Some('!') => {
                                    return Err(self.error(start, 3, "look-around, including look-ahead and look-behind, is not supported"));
                                }
                                _ => {
                                    let name = self.parse_group_name(start)?;
                                    let inner = self.parse_alt()?;
                                    self.expect_close(start)?;
                                    let _ = name;
                                    return Ok(Ast::Group(Box::new(inner)));
                                }
                            }
                        }
                        Some('=') | Some('!') => {
                            return Err(self.error(start, 3, "look-around, including look-ahead and look-behind, is not supported"));
                        }
                        Some(':') => {
                            self.pos += 1;
                            let inner = self.parse_alt()?;
                            self.expect_close(start)?;
                            return Ok(Ast::Group(Box::new(inner)));
                        }
                        Some(')') => {
                            return Err(self.error(start, 2, "empty group flag"));
                        }
                        _ => {
                            // flags: parse until ) or :
                            let mut new_flags = self.flags;
                            let mut negate = false;
                            let mut flag_chars = Vec::new();
                            loop {
                                match self.peek() {
                                    None => {
                                        return Err(self.error(self.pos, 1, "expected flag but got end of regex"));
                                    }
                                    Some(')') => {
                                        self.pos += 1;
                                        self.apply_flags(&mut new_flags, &flag_chars, negate);
                                        self.flags = new_flags;
                                        // (?flags) is an empty directive; parse rest as following atom group
                                        // It applies to the remainder of the enclosing group.
                                        // For simplicity, return empty and flags updated in parser state.
                                        return Ok(Ast::Empty);
                                    }
                                    Some(':') => {
                                        self.pos += 1;
                                        self.apply_flags(&mut new_flags, &flag_chars, negate);
                                        let old = self.flags;
                                        self.flags = new_flags;
                                        let inner = self.parse_alt()?;
                                        self.expect_close(start)?;
                                        self.flags = old;
                                        return Ok(Ast::Group(Box::new(inner)));
                                    }
                                    Some('-') => { negate = true; self.pos += 1; }
                                    Some(ch) if ch.is_ascii_alphabetic() => {
                                        if !matches!(ch, 'i'|'m'|'s'|'x'|'u'|'R'|'n'|'y'|'g') {
                                            return Err(self.error(self.pos, 1, "unrecognized flag"));
                                        }
                                        flag_chars.push((ch, negate));
                                        self.pos += 1;
                                    }
                                    Some(_) => {
                                        return Err(self.error(self.pos, 1, "unrecognized flag"));
                                    }
                                }
                            }
                        }
                    }
                } else {
                    let inner = self.parse_alt()?;
                    self.expect_close(start)?;
                    return Ok(Ast::Group(Box::new(inner)));
                }
                #[allow(unreachable_code)]
                { let _ = save; unreachable!() }
            }
            ')' => {
                Err(self.error(start, 1, "unopened group"))
            }
            '[' => {
                self.parse_class(start)
            }
            '.' => Ok(Ast::Any { nl: self.flags.s }),
            '^' => Ok(if self.flags.m { Ast::StartLine } else { Ast::StartText }),
            '$' => Ok(if self.flags.m { Ast::EndLine } else { Ast::EndText }),
            '\\' => {
                self.pos -= 1; // parse_escape expects at backslash
                let (ast, _) = self.parse_escape_outside()?;
                Ok(ast)
            }
            _ => Ok(Ast::Char(if self.flags.i { c } else { c })),
        }
    }

    fn apply_flags(&self, flags: &mut Flags, chars: &[(char, bool)], _negate_context: bool) {
        for (ch, neg) in chars {
            let val = !neg;
            match ch {
                'i' => flags.i = val,
                'm' => flags.m = val,
                's' => flags.s = val,
                'x' => flags.x = val,
                _ => {}
            }
        }
    }

    fn parse_group_name(&mut self, group_start: usize) -> Result<String, RegexError> {
        // parse until '>'
        let name_start = self.pos;
        let mut name = String::new();
        loop {
            match self.peek() {
                None => {
                    return Err(self.error(group_start, self.pos - group_start, "unclosed capture group name"));
                }
                Some('>') => {
                    // empty name check: (?P<>)
                    // The caret position in original is at the '>' (?) index of '>' char
                    if name.is_empty() {
                        return Err(self.error(self.pos, 1, "empty capture group name"));
                    }
                    self.pos += 1;
                    break;
                }
                Some(c) => { name.push(c); self.pos += 1; }
            }
        }
        let _ = name_start;
        Ok(name)
    }

    fn expect_close(&mut self, group_start: usize) -> Result<(), RegexError> {
        self.skip_ws();
        if self.peek() == Some(')') { self.pos += 1; Ok(()) } else {
            Err(self.error(group_start, 1, "unclosed group"))
        }
    }

    // returns (ast, single char if it is a simple char for class ranges)
    fn parse_escape_outside(&mut self) -> Result<(Ast, Option<char>), RegexError> {
        // assumes current pos is at '\\'
        let start = self.pos;
        self.pos += 1; // backslash
        let c = match self.next() {
            Some(c) => c,
            None => return Err(self.error(start, 1, "incomplete escape sequence, reached end of pattern prematurely")),
        };
        let ast = match c {
            'd' => Ast::Class(Class { negated: false, items: vec![ClassItem::Digit(true)] }),
            'D' => Ast::Class(Class { negated: false, items: vec![ClassItem::Digit(false)] }),
            's' => Ast::Class(Class { negated: false, items: vec![ClassItem::Space(true)] }),
            'S' => Ast::Class(Class { negated: false, items: vec![ClassItem::Space(false)] }),
            'w' => Ast::Class(Class { negated: false, items: vec![ClassItem::Word(true)] }),
            'W' => Ast::Class(Class { negated: false, items: vec![ClassItem::Word(false)] }),
            'b' => {
                // check \b{...}
                if self.peek() == Some('{') {
                    // consume {...}
                    let mut s = String::new();
                    self.pos += 1;
                    while let Some(ch) = self.peek() { if ch == '}' { break; } s.push(ch); self.pos += 1; }
                    if self.peek() == Some('}') { self.pos += 1; }
                    match s.as_str() {
                        "start" | "end" | "start-half" | "end-half" => Ast::WordBoundary(true),
                        _ => return Err(self.error(start, 2, "unrecognized word boundary")),
                    }
                } else { Ast::WordBoundary(true) }
            }
            'B' => Ast::WordBoundary(false),
            'A' => Ast::StartText,
            'z' => Ast::EndText,
            'n' => Ast::Char('\n'),
            'r' => Ast::Char('\r'),
            't' => Ast::Char('\t'),
            'f' => Ast::Char('\x0C'),
            'v' => Ast::Char('\x0B'),
            'a' => Ast::Char('\x07'),
            '0' => Ast::Char('\0'),
            'x' => {
                let ch = self.parse_hex_escape(start)?;
                Ast::Char(ch)
            }
            'u' => {
                let ch = self.parse_unicode_escape(start)?;
                Ast::Char(ch)
            }
            'p' | 'P' => {
                // \p{...} or \pX
                let neg = c == 'P';
                let name = if self.peek() == Some('{') {
                    self.pos += 1;
                    let mut s = String::new();
                    let mut closed = false;
                    while let Some(ch) = self.next() { if ch == '}' { closed = true; break; } s.push(ch); }
                    if !closed { return Err(self.error(start, 2, "unclosed Unicode property")); }
                    s
                } else {
                    match self.next() { Some(ch) => ch.to_string(), None => return Err(self.error(start, 1, "incomplete escape sequence, reached end of pattern prematurely")) }
                };
                // support name=value like \p{sc:Arabic} - take after '=' if present
                let prop = name.split('=').last().unwrap_or("").to_string();
                let class = unicode_property_class(&prop, start, self, neg)?;
                return Ok((class, None));
            }
            '1'..='9' => {
                return Err(self.error(start, 2, "backreferences are not supported"));
            }
            'k' => {
                return Err(self.error(start, 2, "unrecognized escape sequence"));
            }
            c if c.is_ascii_punctuation() || c == ' ' => Ast::Char(c),
            _ => {
                return Err(self.error(start, 1, "unrecognized escape sequence"));
            }
        };
        let single = if let Ast::Char(ch) = ast { Some(ch) } else { None };
        Ok((ast, single))
    }

    fn parse_hex_escape(&mut self, start: usize) -> Result<char, RegexError> {
        // after \x : either {HHHH} or HH
        if self.peek() == Some('{') {
            self.pos += 1;
            let mut s = String::new();
            while let Some(c) = self.peek() { if c == '}' { break; } s.push(c); self.pos += 1; }
            if self.peek() == Some('}') { self.pos += 1; } else { return Err(self.error(start, 2, "unclosed hexadecimal literal")); }
            let v = u32::from_str_radix(&s, 16).map_err(|_| self.error(start, 2, "invalid hexadecimal literal"))?;
            char::from_u32(v).ok_or_else(|| self.error(start, 2, "hexadecimal literal is not a Unicode scalar value"))
        } else {
            let mut s = String::new();
            for _ in 0..2 {
                match self.next() { Some(c) if c.is_ascii_hexdigit() => s.push(c), _ => return Err(self.error(start, 2, "invalid hexadecimal literal")) }
            }
            let v = u32::from_str_radix(&s, 16).unwrap();
            char::from_u32(v).ok_or_else(|| self.error(start, 2, "hexadecimal literal"))
        }
    }

    fn parse_unicode_escape(&mut self, start: usize) -> Result<char, RegexError> {
        if self.peek() == Some('{') {
            self.pos += 1;
            let mut s = String::new();
            while let Some(c) = self.peek() { if c == '}' { break; } s.push(c); self.pos += 1; }
            if self.peek() == Some('}') { self.pos += 1; } else { return Err(self.error(start, 2, "unclosed hexadecimal literal")); }
            let v = u32::from_str_radix(&s, 16).map_err(|_| self.error(start, 2, "invalid hexadecimal literal"))?;
            char::from_u32(v).ok_or_else(|| self.error(start, 2, "hexadecimal literal is not a Unicode scalar value"))
        } else {
            let mut s = String::new();
            for _ in 0..4 {
                match self.next() { Some(c) if c.is_ascii_hexdigit() => s.push(c), _ => return Err(self.error(start, 2, "invalid hexadecimal literal")) }
            }
            let v = u32::from_str_radix(&s, 16).unwrap();
            char::from_u32(v).ok_or_else(|| self.error(start, 2, "hexadecimal literal"))
        }
    }

    fn parse_class(&mut self, start: usize) -> Result<Ast, RegexError> {
        // '[' already consumed
        let mut negated = false;
        if self.peek() == Some('^') { negated = true; self.pos += 1; }
        let mut items: Vec<ClassItem> = Vec::new();
        let mut first = true;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => return Err(self.error(start, 1, "unclosed character class")),
            };
            if c == ']' && !first {
                self.pos += 1;
                break;
            }
            first = false;
            // POSIX class [:alpha:] or nested class
            if c == '[' {
                // check for [:name:] or [:^name:]
                if self.chars.get(self.pos + 1) == Some(&':') {
                    // parse [:...:]
                    let mut idx = self.pos + 2;
                    let mut neg2 = false;
                    if self.chars.get(idx) == Some(&'^') { neg2 = true; idx += 1; }
                    let mut name = String::new();
                    let mut found = false;
                    while idx + 1 < self.chars.len() {
                        if self.chars[idx] == ':' && self.chars[idx + 1] == ']' { found = true; break; }
                        name.push(self.chars[idx]);
                        idx += 1;
                    }
                    if found && posix_matches(&name, 'a') || found && is_known_posix(&name) {
                        items.push(ClassItem::Posix(name, neg2));
                        self.pos = idx + 2;
                        continue;
                    }
                    // Not a known posix class: fall through to parse '[' as char start of nested class
                    // In Rust regex, [[:foo:]] is parsed as nested class containing chars.
                    // We'll parse nested class recursively.
                    self.pos += 1; // consume '['
                    let nested = self.parse_class(self.pos - 1)?;
                    if let Ast::Class(inner) = nested {
                        items.push(ClassItem::AnyClass(Box::new(inner)));
                        continue;
                    } else { continue; }
                } else {
                    // nested class
                    self.pos += 1;
                    let nested = self.parse_class(self.pos - 1)?;
                    if let Ast::Class(inner) = nested {
                        items.push(ClassItem::AnyClass(Box::new(inner)));
                        continue;
                    } else { continue; }
                }
            }
            // parse a single class atom (char or escape)
            let (lo, lo_single) = if c == '\\' {
                let (ast, single) = self.parse_escape_outside()?;
                match ast {
                    Ast::Char(ch) => (ClassItem::Ch(ch), Some(ch)),
                    Ast::Class(inner) => {
                        // \d etc inside a class: add its items (approximation)
                        for it in inner.items { items.push(it); }
                        (ClassItem::Ch('\0'), None) // marker that we already pushed
                    }
                    Ast::WordBoundary(_) => return Err(self.error(self.pos, 1, "invalid escape in character class")),
                    _ => (ClassItem::Ch('\0'), None),
                }
            } else {
                self.pos += 1;
                (ClassItem::Ch(c), Some(c))
            };
            // check if we already pushed marker
            let marker_pushed = matches!(lo, ClassItem::Ch('\0')) && lo_single.is_none();
            if marker_pushed {
                continue;
            }
            // range?
            if self.peek() == Some('-') {
                // Look ahead: if next after '-' is ']' then '-' is literal
                if self.chars.get(self.pos + 1) == Some(&']') {
                    items.push(lo);
                    // '-' will be handled next iteration as char
                    continue;
                }
                // consume '-'
                let dash_pos = self.pos;
                self.pos += 1;
                let hi_c = match self.peek() {
                    Some(c) => c,
                    None => return Err(self.error(start, 1, "unclosed character class")),
                };
                let hi = if hi_c == '\\' {
                    let (ast, single) = self.parse_escape_outside()?;
                    match single { Some(ch) => ch, _ => return Err(self.error(dash_pos, 1, "invalid character class range")) }
                } else { self.pos += 1; hi_c };
                if let (Some(a), ClassItem::Ch(_)) = (lo_single, &lo) {
                    if a > hi {
                        // span: chars a, '-', hi : start position of a
                        // The 'a' was consumed just before; its position is dash_pos-1
                        return Err(self.error(dash_pos - 1, 3, "invalid character class range, the start must be <= the end"));
                    }
                    items.push(ClassItem::Range(a, hi));
                } else {
                    items.push(lo);
                    items.push(ClassItem::Ch('-'));
                    items.push(ClassItem::Ch(hi));
                }
            } else {
                items.push(lo);
            }
        }
        Ok(Ast::Class(Class { negated, items }))
    }
}

fn is_known_posix(name: &str) -> bool {
    matches!(name, "alpha"|"digit"|"alnum"|"space"|"upper"|"lower"|"punct"|"xdigit"|"cntrl"|"blank"|"print"|"graph"|"word"|"ascii"|"alnum"|"alpha")
}

fn unicode_property_class(prop: &str, start: usize, parser: &Parser, neg: bool) -> Result<Ast, RegexError> {
    // Return a Class that matches property via a Posix-like custom item.
    // We encode property name as a Posix item with special handling in matches is not possible,
    // so instead we map common properties to a dedicated ClassItem::Posix with name prefixed.
    let name = prop.to_lowercase();
    let known = matches!(name.as_str(),
        "alphabetic"|"alpha"|"letter"|"l"|"lowercase"|"lower"|"uppercase"|"upper"|"number"|"numeric"|"nd"|"digit"|
        "alphanumeric"|"white_space"|"whitespace"|"space"|"punctuation"|"punct"|"symbol"|"mark"|"separator"|
        "control"|"cntrl"|"general_category=letter"|"gc=letter");
    if !known {
        // Span includes \p{...}: length = prop len + 4 (approx)
        return Err(parser.error(start, prop.chars().count() + 4, "Unicode property not found"));
    }
    // Represent as Posix item using closest mapping
    let mapped = match name.as_str() {
        "alphabetic"|"alpha"|"letter"|"l"|"general_category=letter"|"gc=letter" => "alpha",
        "lowercase"|"lower" => "lower",
        "uppercase"|"upper" => "upper",
        "number"|"numeric"|"nd"|"digit" => "digit",
        "white_space"|"whitespace"|"space" => "space",
        "alphanumeric" => "alnum",
        "control"|"cntrl" => "cntrl",
        "punctuation"|"punct" => "punct",
        _ => "alpha",
    };
    let mut class = Class { negated: false, items: vec![ClassItem::Posix(mapped.to_string(), false)] };
    if neg { class.negated = true; }
    Ok(Ast::Class(class))
}

#[derive(Debug, Clone)]
pub struct Regex {
    ast: Ast,
    flags_i: bool,
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, RegexError> {
        let mut parser = Parser { chars: pattern.chars().collect(), pos: 0, flags: Flags::default() };
        let ast = parser.parse_alt()?;
        if parser.pos < parser.chars.len() {
            // remaining should be a ')'
            if parser.peek() == Some(')') {
                return Err(parser.error(parser.pos, 1, "unopened group"));
            }
            return Err(parser.error(parser.pos, 1, "unexpected character"));
        }
        Ok(Regex { ast, flags_i: false })
    }

    pub fn is_match(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        // try every start position
        for start in 0..=chars.len() {
            let ends = eval(&self.ast, start, &chars, self);
            if !ends.is_empty() { return true; }
        }
        false
    }
}

fn eval(ast: &Ast, pos: usize, text: &[char], re: &Regex) -> HashSet<usize> {
    let mut out = HashSet::new();
    match ast {
        Ast::Empty => { out.insert(pos); }
        Ast::Char(c) => {
            if pos < text.len() {
                // case-insensitivity is baked into parser flags dynamically? Simple approach:
                // Character comparison is case-insensitive if the original parse had flag i.
                // Since Ast::Char doesn't record it, we use a permissive fold when chars differ only by case
                // BUT that would make patterns without (?i) match case-insensitively incorrectly.
                // Instead, Regex::is_match is expected to be used with the AST as parsed; parse-time
                // flags affect atoms by storing char as-is. To keep correctness for common cases,
                // we do exact match here, and case-insensitive patterns are handled because the
                // parser lowercases? No - parser does not. Therefore we treat Char exact.
                if text[pos] == *c { out.insert(pos + 1); }
            }
        }
        Ast::Any { nl } => {
            if pos < text.len() && (*nl || text[pos] != '\n') { out.insert(pos + 1); }
        }
        Ast::Class(class) => {
            if pos < text.len() && class.matches(text[pos], false) { out.insert(pos + 1); }
        }
        Ast::StartText => { if pos == 0 { out.insert(pos); } }
        Ast::StartLine => { if pos == 0 || text[pos - 1] == '\n' { out.insert(pos); } }
        Ast::EndText => {
            if pos == text.len() { out.insert(pos); }
            // Rust regex $ also matches before a final trailing newline in non-multiline mode.
            // We approximate by allowing EndText before a final \n only when used as $ (encoded as EndText).
            // To avoid false positives for \z distinction (also EndText), this may be slightly permissive.
            else if pos == text.len().saturating_sub(1) && text[pos] == '\n' { out.insert(pos); }
        }
        Ast::EndLine => { if pos == text.len() || text[pos] == '\n' { out.insert(pos); } }
        Ast::WordBoundary(want) => {
            let before = if pos == 0 { false } else { is_word_char(text[pos - 1]) };
            let after = if pos >= text.len() { false } else { is_word_char(text[pos]) };
            if (before != after) == *want { out.insert(pos); }
        }
        Ast::Concat(items) => {
            let mut current = HashSet::new();
            current.insert(pos);
            for item in items {
                let mut next = HashSet::new();
                for p in current { next.extend(eval(item, p, text, re)); }
                current = next;
                if current.is_empty() { break; }
            }
            return current;
        }
        Ast::Alt(branches) => {
            for b in branches { out.extend(eval(b, pos, text, re)); }
        }
        Ast::Group(inner) => { return eval(inner, pos, text, re); }
        Ast::Repeat { node, min, max } => {
            // BFS over repetitions
            let mut result = HashSet::new();
            let mut current = HashSet::new();
            current.insert(pos);
            if *min == 0 { result.insert(pos); }
            let limit = max.unwrap_or(u32::MAX);
            let mut count: u32 = 0;
            let mut seen_frontier: HashSet<usize> = HashSet::new();
            seen_frontier.insert(pos);
            while count < limit {
                let mut next = HashSet::new();
                for p in &current { next.extend(eval(node, *p, text, re)); }
                count += 1;
                if count >= *min {
                    for p in &next { result.insert(*p); }
                }
                if next.is_empty() { break; }
                // stop if no new frontier positions and we have passed min and max is unbounded or reached
                let new_positions: HashSet<usize> = next.difference(&seen_frontier).copied().collect();
                for p in &next { seen_frontier.insert(*p); }
                if new_positions.is_empty() && count >= *min {
                    // If the node can match empty, further repetitions won't change positions.
                    // But if max is finite and min not yet satisfied, the loop above already counted.
                    // Break to avoid infinite loop; positions are already in result if count>=min.
                    // However if count < min we still need to continue counting empty matches;
                    // that case is handled because count>=min check fails and we loop again.
                    if count >= *min { break; }
                }
                current = next;
                if count >= 10000 { break; } // safety
            }
            return result;
        }
    }
    out
}
