#[derive(Debug, Clone, PartialEq)]
pub enum OutputFormat {
    Binary,
    Si,
    Fixed(u64, char), // divisor, suffix
}

pub fn format_size(size: u64, fmt: &OutputFormat, filecount: bool) -> String {
    if filecount {
        return size.to_string();
    }
    match fmt {
        OutputFormat::Binary => human(size, 1024),
        OutputFormat::Si => human(size, 1000),
        OutputFormat::Fixed(div, suffix) => {
            if *div == 1 {
                format!("{}B", size)
            } else {
                format!("{}{}", size / div, suffix)
            }
        }
    }
}

fn human(size: u64, base: u64) -> String {
    if size < base {
        return format!("{}B", size);
    }
    let units = ['B', 'K', 'M', 'G', 'T', 'P'];
    let mut exp = 0usize;
    let mut div: u64 = 1;
    while exp < 5 {
        match div.checked_mul(base) {
            Some(n) if n <= size => { div = n; exp += 1; }
            _ => break,
        }
    }
    let suffix = units[exp];
    if size / div < 10 {
        format!("{:.1}{}", size as f64 / div as f64, suffix)
    } else {
        format!("{}{}", size / div, suffix)
    }
}

// Parse the loose output-format used in the config file.
pub fn parse_config_output_format(s: &str) -> OutputFormat {
    let lower = s.to_lowercase();
    if lower == "si" {
        return OutputFormat::Si;
    }
    for (prefix, divisor, suffix) in [
        ("kb", 1000u64, 'K'),
        ("mb", 1000u64 * 1000, 'M'),
        ("gb", 1000u64 * 1000 * 1000, 'G'),
        ("tb", 1000u64 * 1000 * 1000 * 1000, 'T'),
        ("pb", 1000u64 * 1000 * 1000 * 1000 * 1000, 'P'),
    ] {
        if lower.starts_with(prefix) {
            return OutputFormat::Fixed(divisor, suffix);
        }
    }
    match lower.chars().next() {
        Some('b') => OutputFormat::Fixed(1, 'B'),
        Some('k') => OutputFormat::Fixed(1024, 'K'),
        Some('m') => OutputFormat::Fixed(1024 * 1024, 'M'),
        Some('g') => OutputFormat::Fixed(1024 * 1024 * 1024, 'G'),
        Some('t') => OutputFormat::Fixed(1024u64 * 1024 * 1024 * 1024, 'T'),
        Some('p') => OutputFormat::Fixed(1024u64 * 1024 * 1024 * 1024 * 1024, 'P'),
        _ => OutputFormat::Binary,
    }
}

// Parse --min-size values. Returns None for unparsable (meaning: no filtering).
pub fn parse_min_size(s: &str) -> Option<u64> {
    let t = s.trim();
    if t.is_empty() { return None; }
    // numeric part: optional leading '+' followed by digits
    let bytes = t.as_bytes();
    let mut idx = 0usize;
    if idx < bytes.len() && bytes[idx] == b'+' { idx += 1; }
    let num_start = 0usize;
    let mut num_end = idx;
    while num_end < bytes.len() && bytes[num_end].is_ascii_digit() { num_end += 1; }
    if num_end == idx {
        // no digits (covers "" , "K", "-1" after clap attached form, etc)
        return None;
    }
    let num_str = &t[num_start..num_end];
    // strip a leading '+' for parse (u64 parse accepts it, keep as is)
    let value: u64 = match num_str.parse::<u64>() {
        Ok(v) => v,
        Err(_) => return None,
    };
    let suffix = &t[num_end..];
    if suffix.is_empty() { return Some(value); }
    let lower = suffix.to_lowercase();
    let first = lower.chars().next().unwrap();
    let exponent: u32 = match first {
        'b' => 0,
        'k' => 1,
        'm' => 2,
        'g' => 3,
        't' => 4,
        'p' => 5,
        c if !c.is_alphabetic() => 0,
        _ => return None,
    };
    let binary = suffix.len() == 1 || lower.contains('i');
    let base: u64 = if binary { 1024 } else { 1000 };
    let mult = base.pow(exponent);
    Some(value.saturating_mul(mult))
}
