    fn localtime_r(timep: *const i64, result: *mut CTm) -> *mut CTm;
}

pub struct LocalDateTime {
    pub year: i64,
    pub mon: i64, // 1-12
    pub mday: i64,
    pub hour: i64,
    pub min: i64,
    pub sec: i64,
}

pub fn local_from_unix(secs: i64) -> LocalDateTime {
    let mut tm = CTm {
        tm_sec: 0, tm_min: 0, tm_hour: 0, tm_mday: 0, tm_mon: 0, tm_year: 0,
        tm_wday: 0, tm_yday: 0, tm_isdst: 0, tm_gmtoff: 0, tm_zone: std::ptr::null(),
    };
    let r = unsafe { localtime_r(&secs as *const i64, &mut tm as *mut CTm) };
    if !r.is_null() {
        return LocalDateTime {
            year: tm.tm_year as i64 + 1900,
            mon: tm.tm_mon as i64 + 1,
            mday: tm.tm_mday as i64,
            hour: tm.tm_hour as i64,
            min: tm.tm_min as i64,
            sec: tm.tm_sec as i64,
        };
    }
    // fallback UTC
    let days = secs.div_euclid(86400);
    let secs_of_day = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    LocalDateTime { year: y, mon: m, mday: d, hour: secs_of_day / 3600, min: (secs_of_day % 3600) / 60, sec: secs_of_day % 60 }
}

pub fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    // Howard Hinnant algorithm, days since 1970-01-01
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400; // [0,399]
    let mp = (m + 9) % 12; // [0,11]
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn format_timestamp(secs: u64) -> String {
    // secs may exceed i64 for absurd sums; clamp
    let s = if secs > i64::MAX as u64 { i64::MAX } else { secs as i64 };
    let dt = local_from_unix(s);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", dt.year, dt.mon, dt.mday, dt.hour, dt.min, dt.sec)
}

pub fn system_time_abs_secs(t: SystemTime) -> u64 {
    match t.duration_since(UNIX_EPOCH) {
        Ok(d) => d.as_secs(),
        Err(e) => e.duration().as_secs(),
    }
}

pub fn system_time_from_signed(secs: i64, nsec: i64) -> SystemTime {
    let nsec_u = if nsec < 0 { 0 } else { nsec as u32 };
    if secs >= 0 {
        UNIX_EPOCH + Duration::new(secs as u64, nsec_u)
    } else {
        // nsec in MetadataExt is nanoseconds part (can be negative adjustment?). Approximate.
        let mag = (-secs) as u64;
        if mag == 0 { UNIX_EPOCH } else { UNIX_EPOCH - Duration::new(mag, 0) }
    }
}
