pub fn glob_match(pattern: &str, text: &str) -> bool {
    // glob with * and ? matching whole string, char-wise
    let p: Vec<char> = pattern.chars().collect();
    let t: Vec<char> = text.chars().collect();
    glob_rec(&p, 0, &t, 0)
}

fn glob_rec(p: &[char], mut pi: usize, t: &[char], mut ti: usize) -> bool {
    while pi < p.len() {
        match p[pi] {
            '*' => {
                // collapse *
                while pi < p.len() && p[pi] == '*' { pi += 1; }
                if pi >= p.len() { return true; }
                for skip in 0..=(t.len() - ti) {
                    if glob_rec(p, pi, t, ti + skip) { return true; }
                }
                return false;
            }
            '?' => {
                if ti >= t.len() { return false; }
                pi += 1; ti += 1;
            }
            c => {
                if ti >= t.len() || t[ti] != c { return false; }
                pi += 1; ti += 1;
            }
        }
    }
    ti == t.len()
}

pub fn style_to_ansi_prefix(style: &str) -> Option<String> {
    // Parse lscolors style codes into an ANSI prefix like \x1b[41;37m
    let mut attrs: Vec<String> = Vec::new();
    let mut fg: Option<String> = None;
    let mut bg: Option<String> = None;
    let codes: Vec<&str> = style.split(';').collect();
    let mut i = 0usize;
    while i < codes.len() {
        let code_str = codes[i];
        if code_str.is_empty() { i += 1; continue; }
        let code: i64 = match code_str.parse() {
            Ok(v) => v,
            Err(_) => return None,
        };
        match code {
            0 => { attrs.clear(); fg = None; bg = None; }
            1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9 => {
                let s = code.to_string();
                if !attrs.contains(&s) { attrs.push(s); }
            }
            38 | 48 => {
                // extended color
                let is_fg = code == 38;
                if i + 1 < codes.len() {
                    if codes[i + 1] == "5" && i + 2 < codes.len() {
                        if let Ok(n) = codes[i + 2].parse::<i64>() {
                            let val = format!("{};5;{}", code, n);
                            if is_fg { fg = Some(val); } else { bg = Some(val); }
                            i += 3;
                            continue;
                        }
                    } else if codes[i + 1] == "2" && i + 4 < codes.len() {
                        let val = format!("{};2;{};{};{}", code, codes[i + 2], codes[i + 3], codes[i + 4]);
                        if is_fg { fg = Some(val); } else { bg = Some(val); }
                        i += 5;
                        continue;
                    }
                }
                // invalid extended: ignore
            }
            39 => { fg = None; }
            49 => { bg = None; }
            30..=37 => { fg = Some(code.to_string()); }
            40..=47 => { bg = Some(code.to_string()); }
            90..=97 => { fg = Some(format!("38;5;{}", code - 90 + 8)); }
            100..=107 => { bg = Some(format!("48;5;{}", code - 100 + 8)); }
            _ => {
                // Unknown attribute codes are passed through as attributes by ansi_term-like parsers.
                // To be safe, ignore them.
            }
        }
        i += 1;
    }
    if attrs.is_empty() && fg.is_none() && bg.is_none() { return None; }
    let mut parts: Vec<String> = Vec::new();
    parts.extend(attrs);
    if let Some(b) = bg { parts.push(b); }
    if let Some(f) = fg { parts.push(f); }
    Some(format!("\x1b[{}m", parts.join(";")))
}

pub fn wrap_color(prefix: Option<String>, text: &str) -> String {
    match prefix {
        Some(p) => format!("{}{}\x1b[0m", p, text),
        None => text.to_string(),
    }
}
