use std::collections::HashMap;
use std::fs::Metadata;
use std::os::unix::fs::MetadataExt;
use std::path::Path;

#[derive(Debug, Clone)]
pub struct LsColors {
    indicators: HashMap<String, Option<String>>,
    patterns: Vec<(String, Option<String>)>, // glob, style string
}

fn default_indicators() -> HashMap<String, Option<String>> {
    let mut m = HashMap::new();
    let defaults: [(&str, Option<&str>); 18] = [
        ("fi", None),
        ("di", Some("01;34")),
        ("ln", Some("01;36")),
        ("pi", Some("33")),
        ("so", Some("01;35")),
        ("do", Some("01;35")),
        ("bd", Some("01;33")),
        ("cd", Some("01;33")),
        ("or", Some("40;31;01")),
        ("mi", None),
        ("su", Some("37;41")),
        ("sg", Some("30;43")),
        ("ca", Some("30;41")),
        ("tw", Some("30;42")),
        ("ow", Some("34;42")),
        ("st", Some("37;44")),
        ("ex", Some("01;32")),
        ("mh", None),
    ];
    for (k, v) in defaults { m.insert(k.to_string(), v.map(|s| s.to_string())); }
    m
}

impl LsColors {
    pub fn from_env() -> LsColors {
        let mut indicators = default_indicators();
        let mut patterns = Vec::new();
        if let Ok(val) = std::env::var("LS_COLORS") {
            for entry in val.split(':') {
                if entry.is_empty() { continue; }
                if let Some(eq) = entry.find('=') {
                    let key = &entry[..eq];
                    let value = &entry[eq + 1..];
                    let style = if value.is_empty() { None } else { Some(value.to_string()) };
                    if let Some(stripped) = key.strip_prefix('*') {
                        // key includes leading *, store full glob
                        let _ = stripped;
                        patterns.push((key.to_string(), style));
                    } else {
                        indicators.insert(key.to_string(), style);
                    }
                }
            }
        }
        LsColors { indicators, patterns }
    }

    fn indicator(&self, name: &str) -> Option<String> {
        match self.indicators.get(name) {
            Some(Some(s)) => style_to_ansi_prefix(s),
            _ => None,
        }
    }

    fn pattern_style(&self, filename: &str) -> Option<String> {
        // Later patterns override earlier (GNU ls uses last matching)
        let mut result = None;
        for (glob, style) in &self.patterns {
            if glob_match(glob, filename) {
                if let Some(s) = style { result = style_to_ansi_prefix(s); } else { result = None; }
            }
        }
        result
    }

    pub fn style_prefix_for_path(&self, path: &Path) -> Option<String> {
        let filename = path.file_name().map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| path.to_string_lossy().to_string());
        match std::fs::metadata(path) {
            Ok(md) => self.style_for_metadata(&md, &filename),
            Err(_) => {
                if let Some(p) = self.pattern_style(&filename) { return Some(p); }
                self.indicator("fi")
            }
        }
    }

    fn style_for_metadata(&self, md: &Metadata, filename: &str) -> Option<String> {
        use std::os::unix::fs::FileTypeExt;
        let ft = md.file_type();
        let mode = md.mode();
        if ft.is_dir() {
            let sticky = mode & 0o1000 != 0;
            let other_write = mode & 0o002 != 0;
            if sticky && other_write { return self.indicator("tw"); }
            if other_write { return self.indicator("ow"); }
            if sticky { return self.indicator("st"); }
            return self.indicator("di");
        }
        if ft.is_fifo() { return self.indicator("pi"); }
        if ft.is_socket() { return self.indicator("so"); }
        if ft.is_block_device() { return self.indicator("bd"); }
        if ft.is_char_device() { return self.indicator("cd"); }
        if ft.is_file() {
            if mode & 0o4000 != 0 { return self.indicator("su"); }
            if mode & 0o2000 != 0 { return self.indicator("sg"); }
            if mode & 0o111 != 0 { return self.indicator("ex"); }
            if md.nlink() > 1 {
                if let Some(p) = self.indicator("mh") { return Some(p); }
            }
            if let Some(p) = self.pattern_style(filename) { return Some(p); }
            return self.indicator("fi");
        }
        // symlink metadata here would be followed metadata, so this is for other types
        if let Some(p) = self.pattern_style(filename) { return Some(p); }
        self.indicator("fi")
    }
}

pub fn glob_match(pattern: &str, text: &str) -> bool {
    // glob with * and ? matching whole string, char-wise
    let p: Vec<char> = pattern.chars().collect();
    let t: Vec<char> = text.chars().collect();
    glob_rec(&p, 0, &t, 0)
}

fn glob_rec(p: &[char], mut pi: usize, t: &[char], mut ti: usize) -> bool {
    while pi < p.len() {
        match p[pi] {
            '*' => {
                // collapse *
                while pi < p.len() && p[pi] == '*' { pi += 1; }
                if pi >= p.len() { return true; }
                for skip in 0..=(t.len() - ti) {
                    if glob_rec(p, pi, t, ti + skip) { return true; }
                }
                return false;
            }
            '?' => {
                if ti >= t.len() { return false; }
                pi += 1; ti += 1;
            }
            c => {
                if ti >= t.len() || t[ti] != c { return false; }
                pi += 1; ti += 1;
            }
        }
    }
    ti == t.len()
}

pub fn style_to_ansi_prefix(style: &str) -> Option<String> {
    // Parse lscolors style codes into an ANSI prefix like \x1b[41;37m
    let mut attrs: Vec<String> = Vec::new();
    let mut fg: Option<String> = None;
    let mut bg: Option<String> = None;
    let codes: Vec<&str> = style.split(';').collect();
    let mut i = 0usize;
    while i < codes.len() {
        let code_str = codes[i];
        if code_str.is_empty() { i += 1; continue; }
        let code: i64 = match code_str.parse() {
            Ok(v) => v,
            Err(_) => return None,
        };
        match code {
            0 => { attrs.clear(); fg = None; bg = None; }
            1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9 => {
                let s = code.to_string();
                if !attrs.contains(&s) { attrs.push(s); }
            }
            38 | 48 => {
                // extended color
                let is_fg = code == 38;
                if i + 1 < codes.len() {
                    if codes[i + 1] == "5" && i + 2 < codes.len() {
                        if let Ok(n) = codes[i + 2].parse::<i64>() {
                            let val = format!("{};5;{}", code, n);
                            if is_fg { fg = Some(val); } else { bg = Some(val); }
                            i += 3;
                            continue;
                        }
                    } else if codes[i + 1] == "2" && i + 4 < codes.len() {
                        let val = format!("{};2;{};{};{}", code, codes[i + 2], codes[i + 3], codes[i + 4]);
                        if is_fg { fg = Some(val); } else { bg = Some(val); }
                        i += 5;
                        continue;
                    }
                }
                // invalid extended: ignore
            }
            39 => { fg = None; }
            49 => { bg = None; }
            30..=37 => { fg = Some(code.to_string()); }
            40..=47 => { bg = Some(code.to_string()); }
            90..=97 => { fg = Some(format!("38;5;{}", code - 90 + 8)); }
            100..=107 => { bg = Some(format!("48;5;{}", code - 100 + 8)); }
            _ => {
                // Unknown attribute codes are passed through as attributes by ansi_term-like parsers.
                // To be safe, ignore them.
            }
        }
        i += 1;
    }
    if attrs.is_empty() && fg.is_none() && bg.is_none() { return None; }
    let mut parts: Vec<String> = Vec::new();
    parts.extend(attrs);
    if let Some(b) = bg { parts.push(b); }
    if let Some(f) = fg { parts.push(f); }
    Some(format!("\x1b[{}m", parts.join(";")))
}

pub fn wrap_color(prefix: Option<String>, text: &str) -> String {
    match prefix {
        Some(p) => format!("{}{}\x1b[0m", p, text),
        None => text.to_string(),
    }
}
