fn def_by_long(name: &str) -> Option<&'static ArgDef> { DEFS.iter().find(|d| d.long == name) }
fn def_by_short(c: char) -> Option<&'static ArgDef> { DEFS.iter().find(|d| d.short == Some(c)) }
fn def_by_id(id: ArgId) -> &'static ArgDef { DEFS.iter().find(|d| d.id == id).unwrap() }

fn canonical(def: &ArgDef) -> String {
    match def.value_name {
        Some(vn) => format!("--{} <{}>", def.long, vn),
        None => format!("--{}", def.long),
    }
}

pub struct ParserState {
    pub bin_name: String,
    used: Vec<ArgId>,          // in encounter order, unique
    used_set: Vec<ArgId>,      // all set flags/values (for conflicts)
    positional_used: bool,
    pending_duplicate: Option<ArgDef>,
}

impl ParserState {
    fn mark_used(&mut self, id: ArgId) {
        if !self.used.contains(&id) { self.used.push(id); }
        if !self.used_set.contains(&id) { self.used_set.push(id); }
    }
    fn smart_usage(&self, extra: Option<ArgId>) -> String {
        let mut parts: Vec<String> = Vec::new();
        let mut ids = self.used.clone();
        if let Some(e) = extra { if !ids.contains(&e) { ids.push(e); } }
        for id in &ids {
            if *id == ArgId::Help || *id == ArgId::Version { continue; }
            parts.push(canonical(def_by_id(*id)));
        }
        let path_part = if self.positional_used { "<PATH>..." } else { "[PATH]..." };
        if parts.is_empty() && !self.positional_used {
            format!("Usage: {} [OPTIONS] [PATH]...", self.bin_name)
        } else if parts.is_empty() {
            format!("Usage: {} {}", self.bin_name, path_part)
        } else {
            format!("Usage: {} {} {}", self.bin_name, parts.join(" "), path_part)
        }
    }
    fn generic_usage(&self) -> String { format!("Usage: {} [OPTIONS] [PATH]...", self.bin_name) }
}

fn err_exit(msg: String) -> ! {
    eprint!("{}", msg);
    std::process::exit(2);
}

fn error_footer() -> &'static str { "\nFor more information, try '--help'.\n" }

impl ParserState {
    fn invalid_utf8_error(&self) -> ! {
        err_exit(format!("error: invalid UTF-8 was detected in one or more arguments\n\n{}\n{}", self.generic_usage(), error_footer()))
    }
    fn unknown_long_error(&self, display: &str, name: &str) -> ! {
        // suggestion?
        if let Some(sugg) = suggest_long(name) {
            let sugg_def = def_by_long(&sugg).unwrap();
            let usage = format!("Usage: {} {} [PATH]...", self.bin_name, canonical(sugg_def));
            err_exit(format!("error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '--{}'\n\n{}\n{}", display, sugg, usage, error_footer()));
        }
        err_exit(format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\n{}", display, display, display, self.smart_usage(None), error_footer()))
    }
    fn unknown_short_error(&self, c: char) -> ! {
        let display = format!("-{}", c);
        err_exit(format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\n{}", display, display, display, self.generic_usage(), error_footer()))
    }
    fn unexpected_value_error(&self, def: &ArgDef, value: &str) -> ! {
        let usage = self.smart_usage(Some(def.id));
        err_exit(format!("error: unexpected value '{}' for '--{}' found; no more were expected\n\n{}\n{}", value, def.long, usage, error_footer()))
    }
    fn missing_value_error(&self, def: &ArgDef) -> ! {
        let mut s = format!("error: a value is required for '{}' but none was supplied\n", canonical(def));
        if def.id == ArgId::OutputFormat {
            s.push_str("  [possible values: si, b, k, m, g, t, kb, mb, gb, tb]\n");
        } else if def.id == ArgId::Filetime {
            s.push_str("  [possible values: a, c, m]\n");
        }
        s.push_str(&format!("\n{}", error_footer()));
        err_exit(s)
    }
    fn duplicate_error(&self, def: &ArgDef) -> ! {
        err_exit(format!("error: the argument '{}' cannot be used multiple times\n\n{}\n{}", canonical(def), self.generic_usage(), error_footer()))
    }
    fn invalid_value_error(&self, def: &ArgDef, value: &str, reason: Option<String>) -> ! {
        if def.id == ArgId::OutputFormat || def.id == ArgId::Filetime {
            let (values_str, candidates): (&str, Vec<&str>) = if def.id == ArgId::OutputFormat {
                ("si, b, k, m, g, t, kb, mb, gb, tb", vec!["si","b","k","m","g","t","kb","mb","gb","tb"])
            } else {
                ("a, c, m", vec!["a","c","m"])
            };
            let mut s = format!("error: invalid value '{}' for '{}'\n  [possible values: {}]\n", value, canonical(def), values_str);
            if let Some(tip) = suggest_value(value, &candidates) {
                s.push_str(&format!("\n  tip: a similar value exists: '{}'\n", tip));
            }
            s.push_str(&format!("\n{}", error_footer()));
            err_exit(s)
        } else {
            let r = reason.unwrap_or_else(|| "invalid value".to_string());
            err_exit(format!("error: invalid value '{}' for '{}': {}\n\n{}", value, canonical(def), r, error_footer()))
        }
    }
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    let max_dist = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a.len()];
    let mut b_match = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = if i > max_dist { i - max_dist } else { 0 };
        let end = (i + max_dist + 1).min(b.len());
        for j in start..end {
            if !b_match[j] && a[i] == b[j] {
                a_match[i] = true; b_match[j] = true; matches += 1; break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mut transpositions = 0usize;
    let mut j = 0usize;
    for i in 0..a.len() {
        if a_match[i] {
            while !b_match[j] { j += 1; }
            if a[i] != b[j] { transpositions += 1; }
            j += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - transpositions as f64 / 2.0) / m) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j <= 0.7 { return j; }
    let prefix = a.chars().zip(b.chars()).take(4).take_while(|(x, y)| x == y).count();
    j + prefix as f64 * 0.1 * (1.0 - j)
}

fn suggest_value<'a>(value: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let mut best: Option<(&str, f64)> = None;
    for cand in candidates {
        let score = jaro_winkler(value, cand);
        if score > 0.7 {
            if best.map(|(_, s)| score > s).unwrap_or(true) { best = Some((cand, score)); }
        }
    }
    best.map(|(c, _)| c)
}

fn suggest_long(name: &str) -> Option<String> {
    let mut best: Option<(String, f64)> = None;
    for def in DEFS {
        let score = jaro_winkler(name, def.long);
        if score > 0.8 {
            if best.as_ref().map(|(_, s)| score > *s).unwrap_or(true) { best = Some((def.long.to_string(), score)); }
        }
    }
    best.map(|(c, _)| c)
}

fn is_enum_def(id: ArgId) -> bool { matches!(id, ArgId::OutputFormat | ArgId::Filetime) }

pub fn bin_name_from_argv0(argv0: Option<&OsString>) -> String {
    if let Some(a) = argv0 {
        let s = a.to_string_lossy();
        let path = std::path::Path::new(s.as_ref());
        if let Some(name) = path.file_name() {
            let n = name.to_string_lossy().to_string();
            if !n.is_empty() { return n; }
        }
        if !s.is_empty() { return s.to_string(); }
    }
    "Dust".to_string()
}

pub fn print_version() -> ! {
    println!("Dust 1.2.3");
    std::process::exit(0);
}

pub fn parse_cli() -> (Cli, ParserState) {
    let argv: Vec<OsString> = std::env::args_os().collect();
    let bin_name = bin_name_from_argv0(argv.get(0));
    let mut state = ParserState { bin_name, used: Vec::new(), used_set: Vec::new(), positional_used: false, pending_duplicate: None };
    let mut cli = Cli::default();
    let args: Vec<OsString> = argv.iter().skip(1).cloned().collect();
    let mut i = 0usize;
    let mut positional_mode = false;

    while i < args.len() {
        let token_os = &args[i];
        let token_bytes = token_os.as_bytes();
        if positional_mode {
            add_path(&mut cli, &mut state, token_os);
            i += 1;
            continue;
        }
        if token_bytes == b"--" {
            positional_mode = true;
            i += 1;
            continue;
        }
        if token_bytes == b"-" {
            add_path(&mut cli, &mut state, token_os);
            i += 1;
            continue;
        }
        if token_bytes.starts_with(b"--") {
            // long
            let body_lossy = String::from_utf8_lossy(&token_bytes[2..]).to_string();
            let (name, value_part) = match body_lossy.find('=') {
                Some(idx) => (body_lossy[..idx].to_string(), Some(body_lossy[idx + 1..].to_string())),
                None => (body_lossy.clone(), None),
            };
            let def = def_by_long(&name);
            match def {
                None => {
                    let display = format!("--{}", name);
                    state.unknown_long_error(&display, &name);
                }
                Some(def) => {
                    let def = *def;
                    if def.id == ArgId::Help {
                        if let Some(v) = value_part { state.unexpected_value_error(&def, &v); }
                        print_help_long(&state.bin_name);
                    }
                    if def.id == ArgId::Version {
                        if let Some(v) = value_part { state.unexpected_value_error(&def, &v); }
                        print_version();
                    }
                    if !def.is_value {
                        if let Some(v) = value_part { state.unexpected_value_error(&def, &v); }
                        set_flag(&mut cli, &mut state, def);
                        i += 1;
                        continue;
                    } else {
                        // value option
                        let raw: String;
                        if let Some(v) = value_part {
                            if v.is_empty() && is_enum_def(def.id) {
                                state.missing_value_error(&def);
                            }
                            raw = v;
                            i += 1;
                        } else {
                            // need next
                            let (v, consumed) = take_next_value(&args, i, &def, &mut state);
                            raw = v;
                            i += consumed;
                        }
                        set_value(&mut cli, &mut state, def, raw);
                        continue;
                    }
                }
            }
        } else if token_bytes.starts_with(b"-") && token_bytes.len() > 1 {
            // short cluster
            let cluster = String::from_utf8_lossy(&token_bytes[1..]).to_string();
            let chars: Vec<char> = cluster.chars().collect();
            let mut j = 0usize;
            let mut consumed_next = 1usize;
            while j < chars.len() {
                let ch = chars[j];
                if ch == 'h' {
                    print_help_short(&state.bin_name);
                }
                if ch == 'V' {
                    print_version();
                }
                match def_by_short(ch) {
                    None => state.unknown_short_error(ch),
                    Some(def) => {
                        let def = *def;
                        if def.id == ArgId::Help { print_help_short(&state.bin_name); }
                        if def.id == ArgId::Version { print_version(); }
                        if !def.is_value {
                            set_flag(&mut cli, &mut state, def);
                            j += 1;
                            continue;
                        } else {
                            // value is rest of cluster or next arg
                            let rest: String = chars.iter().skip(j + 1).collect();
                            let raw: String;
                            if !rest.is_empty() {
                                if let Some(stripped) = rest.strip_prefix('=') {
                                    if stripped.is_empty() && is_enum_def(def.id) {
                                        state.missing_value_error(&def);
                                    }
                                    raw = stripped.to_string();
                                } else {
                                    raw = rest.clone();
                                }
                            } else {
                                let (v, consumed) = take_next_value(&args, i, &def, &mut state);
                                raw = v;
                                consumed_next = consumed;
                            }
                            set_value(&mut cli, &mut state, def, raw);
                            // rest consumed
                            j = chars.len();
                        }
                    }
                }
            }
            i += consumed_next;
            continue;
        } else {
            add_path(&mut cli, &mut state, token_os);
            i += 1;
            continue;
        }
    }

    // pending duplicate for value options
    if let Some(def) = state.pending_duplicate {
        state.duplicate_error(&def);
    }
    // conflicts (post-parse)
    check_conflicts(&cli, &state);
    (cli, state)
}

fn add_path(cli: &mut Cli, state: &mut ParserState, token_os: &OsString) {
    state.positional_used = true;
    match token_os.to_str() {
        Some(s) => cli.paths.push(s.to_string()),
        None => state.invalid_utf8_error(),
    }
}

fn take_next_value(args: &[OsString], i: usize, def: &ArgDef, state: &mut ParserState) -> (String, usize) {
    // returns (value, number of tokens consumed including current)
    if i + 1 >= args.len() {
        state.missing_value_error(def);
    }
    let next = &args[i + 1];
    let next_bytes = next.as_bytes();
    let allow_hyphen = matches!(def.id, ArgId::Mtime | ArgId::Atime | ArgId::Ctime);
    if allow_hyphen {
        match next.to_str() {
            Some(s) => return (s.to_string(), 2),
            None => state.invalid_utf8_error(),
        }
    }
    if next_bytes == b"--" {
        state.missing_value_error(def);
    }
    if next_bytes.starts_with(b"-") && next_bytes.len() > 1 {
        // decide missing vs unknown
        if next_bytes.starts_with(b"--") {
            let body = String::from_utf8_lossy(&next_bytes[2..]).to_string();
            let name = body.split('=').next().unwrap_or("").to_string();
            if def_by_long(&name).is_some() {
                state.missing_value_error(def);
            } else {
                let display = format!("--{}", name);
                state.unknown_long_error(&display, &name);
            }
        } else {
            let first = String::from_utf8_lossy(&next_bytes[1..]).chars().next().unwrap_or('\0');
            if def_by_short(first).is_some() || first == 'h' || first == 'V' {
                state.missing_value_error(def);
            } else {
                state.unknown_short_error(first);
            }
        }
    }
    match next.to_str() {
        Some(s) => (s.to_string(), 2),
        None => state.invalid_utf8_error(),
    }
}

fn set_flag(cli: &mut Cli, state: &mut ParserState, def: ArgDef) {
    // duplicate check immediate for flags
    if is_flag_set(cli, def.id) {
        state.duplicate_error(&def);
    }
    state.mark_used(def.id);
    match def.id {
        ArgId::FullPaths => cli.full_paths = true,
        ArgId::DereferenceLinks => cli.dereference_links = true,
        ArgId::LimitFilesystem => cli.limit_filesystem = true,
        ArgId::ApparentSize => cli.apparent_size = true,
        ArgId::Reverse => cli.reverse = true,
        ArgId::NoColors => cli.no_colors = true,
        ArgId::ForceColors => cli.force_colors = true,
        ArgId::NoPercentBars => cli.no_percent_bars = true,
        ArgId::BarsOnRight => cli.bars_on_right = true,
        ArgId::ScreenReader => cli.screen_reader = true,
        ArgId::SkipTotal => cli.skip_total = true,
        ArgId::Filecount => cli.filecount = true,
        ArgId::IgnoreHidden => cli.ignore_hidden = true,
        ArgId::FileTypes => cli.file_types = true,
        ArgId::NoProgress => cli.no_progress = true,
        ArgId::PrintErrors => cli.print_errors = true,
        ArgId::OnlyDir => cli.only_dir = true,
        ArgId::OnlyFile => cli.only_file = true,
        ArgId::OutputJson => cli.output_json = true,
        _ => {}
    }
}

fn is_flag_set(cli: &Cli, id: ArgId) -> bool {
    match id {
        ArgId::FullPaths => cli.full_paths,
        ArgId::DereferenceLinks => cli.dereference_links,
        ArgId::LimitFilesystem => cli.limit_filesystem,
        ArgId::ApparentSize => cli.apparent_size,
        ArgId::Reverse => cli.reverse,
        ArgId::NoColors => cli.no_colors,
        ArgId::ForceColors => cli.force_colors,
        ArgId::NoPercentBars => cli.no_percent_bars,
        ArgId::BarsOnRight => cli.bars_on_right,
        ArgId::ScreenReader => cli.screen_reader,
        ArgId::SkipTotal => cli.skip_total,
        ArgId::Filecount => cli.filecount,
        ArgId::IgnoreHidden => cli.ignore_hidden,
        ArgId::FileTypes => cli.file_types,
        ArgId::NoProgress => cli.no_progress,
        ArgId::PrintErrors => cli.print_errors,
        ArgId::OnlyDir => cli.only_dir,
        ArgId::OnlyFile => cli.only_file,
        ArgId::OutputJson => cli.output_json,
        _ => false,
    }
}

fn is_value_set(cli: &Cli, id: ArgId) -> bool {
    match id {
        ArgId::Depth => cli.depth.is_some(),
        ArgId::Threads => cli.threads.is_some(),
        ArgId::Config => cli.config.is_some(),
        ArgId::NumberOfLines => cli.number_of_lines.is_some(),
        ArgId::IgnoreAllInFile => cli.ignore_all_in_file.is_some(),
        ArgId::MinSize => cli.min_size.is_some(),
        ArgId::TerminalWidth => cli.terminal_width.is_some(),
        ArgId::OutputFormat => cli.output_format.is_some(),
        ArgId::StackSize => cli.stack_size.is_some(),
        ArgId::Mtime => cli.mtime.is_some(),
        ArgId::Atime => cli.atime.is_some(),
        ArgId::Ctime => cli.ctime.is_some(),
        ArgId::Files0From => cli.files0_from.is_some(),
        ArgId::FilesFrom => cli.files_from.is_some(),
        ArgId::Filetime => cli.filetime.is_some(),
        _ => false,
    }
}

fn set_value(cli: &mut Cli, state: &mut ParserState, def: ArgDef, raw: String) {
    if !def.is_multi && is_value_set(cli, def.id) {
        if state.pending_duplicate.is_none() {
            state.pending_duplicate = Some(def);
        }
        state.mark_used(def.id);
        return;
    }
    state.mark_used(def.id);
    // validate and store
    match def.id {
        ArgId::Depth => cli.depth = Some(parse_usize_value(state, &def, &raw)),
        ArgId::Threads => cli.threads = Some(parse_usize_value(state, &def, &raw)),
        ArgId::NumberOfLines => cli.number_of_lines = Some(parse_usize_value(state, &def, &raw)),
        ArgId::TerminalWidth => cli.terminal_width = Some(parse_usize_value(state, &def, &raw)),
        ArgId::StackSize => cli.stack_size = Some(parse_usize_value(state, &def, &raw)),
        ArgId::Config => cli.config = Some(raw),
        ArgId::IgnoreAllInFile => cli.ignore_all_in_file = Some(raw),
        ArgId::MinSize => cli.min_size = Some(raw),
        ArgId::Mtime => cli.mtime = Some(raw),
        ArgId::Atime => cli.atime = Some(raw),
        ArgId::Ctime => cli.ctime = Some(raw),
        ArgId::Files0From => cli.files0_from = Some(raw),
        ArgId::FilesFrom => cli.files_from = Some(raw),
        ArgId::IgnoreDirectory => cli.ignore_directory.push(raw),
        ArgId::InvertFilter => cli.invert_filter.push(raw),
        ArgId::Filter => cli.filter.push(raw),
        ArgId::Collapse => cli.collapse.push(raw),
        ArgId::OutputFormat => cli.output_format = Some(parse_output_format_value(state, &def, &raw)),
        ArgId::Filetime => cli.filetime = Some(parse_filetime_value(state, &def, &raw)),
        _ => {}
    }
}

fn parse_usize_value(state: &ParserState, def: &ArgDef, raw: &str) -> usize {
    match raw.parse::<usize>() {
        Ok(v) => v,
        Err(e) => state.invalid_value_error(def, raw, Some(e.to_string())),
    }
}

fn parse_output_format_value(state: &ParserState, def: &ArgDef, raw: &str) -> OutputFormat {
    let lower = raw.to_lowercase();
    match lower.as_str() {
        "si" => OutputFormat::Si,
        "b" => OutputFormat::Fixed(1, 'B'),
        "k" | "kib" => OutputFormat::Fixed(1024, 'K'),
        "m" | "mib" => OutputFormat::Fixed(1024 * 1024, 'M'),
        "g" | "gib" => OutputFormat::Fixed(1024 * 1024 * 1024, 'G'),
        "t" | "tib" => OutputFormat::Fixed(1024u64 * 1024 * 1024 * 1024, 'T'),
        "kb" => OutputFormat::Fixed(1000, 'K'),
        "mb" => OutputFormat::Fixed(1000 * 1000, 'M'),
        "gb" => OutputFormat::Fixed(1000 * 1000 * 1000, 'G'),
        "tb" => OutputFormat::Fixed(1000u64 * 1000 * 1000 * 1000, 'T'),
        _ => state.invalid_value_error(def, raw, None),
    }
}

fn parse_filetime_value(state: &ParserState, def: &ArgDef, raw: &str) -> FileTimeKind {
    match raw {
        "a" | "accessed" => FileTimeKind::A,
        "c" | "changed" => FileTimeKind::C,
        "m" | "modified" => FileTimeKind::M,
        _ => state.invalid_value_error(def, raw, None),
    }
}

fn check_conflicts(cli: &Cli, state: &ParserState) {
    // pairs (first in definition is irrelevant; we choose earliest encountered conflicting arg)
    let pairs: &[(ArgId, ArgId)] = &[
        (ArgId::Depth, ArgId::FileTypes),
        (ArgId::InvertFilter, ArgId::Filter),
        (ArgId::InvertFilter, ArgId::FileTypes),
        (ArgId::Filter, ArgId::FileTypes),
        (ArgId::FileTypes, ArgId::OnlyDir),
        (ArgId::OnlyDir, ArgId::OnlyFile),
        (ArgId::Files0From, ArgId::FilesFrom),
    ];
    let is_set = |id: ArgId| -> bool {
        match id {
            ArgId::Depth => cli.depth.is_some(),
            ArgId::FileTypes => cli.file_types,
            ArgId::InvertFilter => !cli.invert_filter.is_empty(),
            ArgId::Filter => !cli.filter.is_empty(),
            ArgId::OnlyDir => cli.only_dir,
            ArgId::OnlyFile => cli.only_file,
            ArgId::Files0From => cli.files0_from.is_some(),
            ArgId::FilesFrom => cli.files_from.is_some(),
            _ => false,
        }
    };
    // encounter order from state.used (which is in encounter order)
    for &first_id in &state.used {
        let mut conflicting: Vec<ArgId> = Vec::new();
        for (a, b) in pairs {
            let other = if *a == first_id { Some(*b) } else if *b == first_id { Some(*a) } else { None };
            if let Some(o) = other {
                if is_set(o) && !conflicting.contains(&o) { conflicting.push(o); }
            }
        }
        if !conflicting.is_empty() {
            let first_def = def_by_id(first_id);
            if conflicting.len() == 1 {
                let other_def = def_by_id(conflicting[0]);
                let usage_first = {
                    // smart usage including only first (and positional marker)
                    let mut s = ParserState { bin_name: state.bin_name.clone(), used: vec![first_id], used_set: vec![], positional_used: state.positional_used, pending_duplicate: None };
                    s.smart_usage(None)
                };
                err_exit(format!("error: the argument '{}' cannot be used with '{}'\n\n{}\n{}", canonical(first_def), canonical(other_def), usage_first, error_footer()));
            } else {
                let mut s = format!("error: the argument '{}' cannot be used with:\n", canonical(first_def));
                for o in &conflicting {
                    s.push_str(&format!("  {}\n", canonical(def_by_id(*o))));
                }
                let usage_first = {
                    let mut st = ParserState { bin_name: state.bin_name.clone(), used: vec![first_id], used_set: vec![], positional_used: state.positional_used, pending_duplicate: None };
                    st.smart_usage(None)
                };
                s.push_str(&format!("\n{}\n{}", usage_first, error_footer()));
                err_exit(s);
            }
        }
    }
}

pub fn print_help_short(bin: &str) -> ! {
    print!("{}", help_short_text(bin));
    std::process::exit(0);
}
pub fn print_help_long(bin: &str) -> ! {
    print!("{}", help_long_text(bin));
    std::process::exit(0);
}

