                    // after value: inline ws/comment then newline or EOF
                    self.skip_ws_inline();
                    match self.peek() { None | Some('\n') | Some('\r') => {}, _ => return Err(()) }
                }
            }
        }
        Ok(top)
    }

    fn parse_key_path(&mut self) -> Result<String, ()> {
        let mut parts: Vec<String> = Vec::new();
        loop {
            self.skip_ws_inline();
            let part = self.parse_key_part()?;
            parts.push(part);
            self.skip_ws_inline();
            if self.peek() == Some('.') { self.pos += 1; continue; } else { break; }
        }
        Ok(parts.join("."))
    }

    fn parse_key_part(&mut self) -> Result<String, ()> {
        match self.peek() {
            Some('"') => {
                let s = self.parse_basic_string()?;
                Ok(format!("\"{}\"", s))
            }
            Some('\'') => {
                let s = self.parse_literal_string()?;
                Ok(format!("'{}'", s))
            }
            Some(c) if c.is_ascii_alphanumeric() || c == '_' || c == '-' => {
                let mut s = String::new();
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == '_' || c == '-' { s.push(c); self.pos += 1; } else { break; }
                }
                Ok(s)
            }
            _ => Err(()),
        }
    }

    fn parse_basic_string(&mut self) -> Result<String, ()> {
        // assumes peek == '"'; handle multiline """
        if self.chars.get(self.pos) == Some(&'"') && self.chars.get(self.pos + 1) == Some(&'"') && self.chars.get(self.pos + 2) == Some(&'"') {
            self.pos += 3;
            let mut s = String::new();
            // skip first newline
            if self.peek() == Some('\r') { self.pos += 1; }
            if self.peek() == Some('\n') { self.pos += 1; }
            loop {
                if self.pos >= self.chars.len() { return Err(()); }
                if self.chars.get(self.pos) == Some(&'"') && self.chars.get(self.pos + 1) == Some(&'"') && self.chars.get(self.pos + 2) == Some(&'"') {
                    self.pos += 3; break;
                }
                let c = self.next().unwrap();
                if c == '\\' {
                    // line-ending backslash or escape
                    let n = self.peek();
                    if n == Some('\n') || n == Some('\r') {
                        while let Some(c) = self.peek() { if c == ' ' || c == '\t' || c == '\n' || c == '\r' { self.pos += 1; } else { break; } }
                        continue;
                    }
                    let e = self.parse_escape()?;
                    s.push(e);
                } else { s.push(c); }
            }
            return Ok(s);
        }
        self.pos += 1; // "
        let mut s = String::new();
        loop {
            match self.next() {
                None => return Err(()),
                Some('"') => break,
                Some('\n') => return Err(()),
                Some('\\') => { let e = self.parse_escape()?; s.push(e); }
                Some(c) => s.push(c),
            }
        }
        Ok(s)
    }

    fn parse_escape(&mut self) -> Result<char, ()> {
        match self.next() {
            Some('b') => Ok('\x08'),
            Some('t') => Ok('\t'),
            Some('n') => Ok('\n'),
            Some('f') => Ok('\x0C'),
            Some('r') => Ok('\r'),
            Some('"') => Ok('"'),
            Some('\\') => Ok('\\'),
            Some('u') => {
                let mut hex = String::new();
                for _ in 0..4 { match self.next() { Some(c) if c.is_ascii_hexdigit() => hex.push(c), _ => return Err(()) } }
                let v = u32::from_str_radix(&hex, 16).map_err(|_| ())?;
                char::from_u32(v).ok_or(())
            }
            Some('U') => {
                let mut hex = String::new();
                for _ in 0..8 { match self.next() { Some(c) if c.is_ascii_hexdigit() => hex.push(c), _ => return Err(()) } }
                let v = u32::from_str_radix(&hex, 16).map_err(|_| ())?;
                char::from_u32(v).ok_or(())
            }
            _ => Err(()),
        }
    }

    fn parse_literal_string(&mut self) -> Result<String, ()> {
        // ''' multiline or '...'
        if self.chars.get(self.pos) == Some(&'\'') && self.chars.get(self.pos + 1) == Some(&'\'') && self.chars.get(self.pos + 2) == Some(&'\'') {
            self.pos += 3;
            if self.peek() == Some('\r') { self.pos += 1; }
            if self.peek() == Some('\n') { self.pos += 1; }
            let mut s = String::new();
            loop {
                if self.pos >= self.chars.len() { return Err(()); }
                if self.chars.get(self.pos) == Some(&'\'') && self.chars.get(self.pos + 1) == Some(&'\'') && self.chars.get(self.pos + 2) == Some(&'\'') { self.pos += 3; break; }
                s.push(self.next().unwrap());
            }
            return Ok(s);
        }
        self.pos += 1;
        let mut s = String::new();
        loop {
            match self.next() {
                None => return Err(()),
                Some('\'') => break,
                Some('\n') => return Err(()),
                Some(c) => s.push(c),
            }
        }
        Ok(s)
    }

    fn parse_value(&mut self) -> Result<TomlValue, ()> {
        match self.peek() {
            Some('"') => Ok(TomlValue::Str(self.parse_basic_string()?)),
            Some('\'') => Ok(TomlValue::Str(self.parse_literal_string()?)),
            Some('[') => { self.parse_array()?; Ok(TomlValue::Array) }
            Some('{') => { self.parse_inline_table()?; Ok(TomlValue::Table) }
            Some(_) => {
                // bare value token until , ] } # newline
                let mut tok = String::new();
                while let Some(c) = self.peek() {
                    if c == '\n' || c == '\r' || c == '#' || c == ',' || c == ']' || c == '}' { break; }
                    tok.push(c); self.pos += 1;
                }
                let tok_trim = tok.trim().to_string();
                if tok_trim.is_empty() { return Err(()); }
                if tok_trim == "true" { return Ok(TomlValue::Bool(true)); }
                if tok_trim == "false" { return Ok(TomlValue::Bool(false)); }
                if let Some(v) = parse_toml_integer(&tok_trim) { return Ok(TomlValue::Int(v)); }
                if is_toml_float(&tok_trim) { return Ok(TomlValue::Float); }
                if is_toml_datetime(&tok_trim) { return Ok(TomlValue::Datetime); }
                Err(())
            }
            None => Err(()),
        }
    }

    fn parse_array(&mut self) -> Result<(), ()> {
        self.pos += 1; // [
        loop {
            self.skip_ws_and_newlines();
            match self.peek() {
                None => return Err(()),
                Some(']') => { self.pos += 1; break; }
                Some(',') => { self.pos += 1; }
                Some(_) => {
                    self.parse_value()?;
                    self.skip_ws_and_newlines();
                    if self.peek() == Some(',') { self.pos += 1; }
                }
            }
        }
        Ok(())
    }

    fn parse_inline_table(&mut self) -> Result<(), ()> {
        self.pos += 1; // {
        loop {
            self.skip_ws_inline();
            match self.peek() {
                None => return Err(()),
                Some('}') => { self.pos += 1; break; }
                Some(',') => { self.pos += 1; }
                Some(_) => {
                    self.parse_key_path()?;
                    self.skip_ws_inline();
                    if self.next() != Some('=') { return Err(()); }
                    self.skip_ws_inline();
                    self.parse_value()?;
                }
            }
        }
        Ok(())
    }
}

fn valid_key_path(s: &str) -> bool {
    // accept bare/quoted/dotted segments
    !s.trim().is_empty()
}

fn unquote_key_path(s: &str) -> String {
    s.trim().to_string()
}

fn parse_toml_integer(tok: &str) -> Option<i128> {
    let t = tok.replace('_', "");
    if t.is_empty() { return None; }
    // hex/oct/bin
    let (sign, rest) = if let Some(r) = t.strip_prefix('-') { (-1i128, r.to_string()) } else if let Some(r) = t.strip_prefix('+') { (1i128, r.to_string()) } else { (1i128, t.clone()) };
    if let Some(hex) = rest.strip_prefix("0x") {
        if hex.is_empty() || !hex.chars().all(|c| c.is_ascii_hexdigit()) { return None; }
        return i128::from_str_radix(hex, 16).ok().map(|v| sign * v);
    }
    if let Some(oct) = rest.strip_prefix("0o") {
        if oct.is_empty() || !oct.chars().all(|c| ('0'..='7').contains(&c)) { return None; }
        return i128::from_str_radix(oct, 8).ok().map(|v| sign * v);
    }
    if let Some(bin) = rest.strip_prefix("0b") {
        if bin.is_empty() || !bin.chars().all(|c| c == '0' || c == '1') { return None; }
        return i128::from_str_radix(bin, 2).ok().map(|v| sign * v);
    }
    // decimal: must be digits only (after sign)
    if rest.is_empty() || !rest.chars().all(|c| c.is_ascii_digit()) { return None; }
    // check no leading zeros issue (TOML forbids leading zeros except 0 itself) - be lenient
    rest.parse::<i128>().ok().map(|v| if t.starts_with('-') { -v } else { v })
}

fn is_toml_float(tok: &str) -> bool {
    let t = tok.replace('_', "");
    if matches!(t.as_str(), "inf" | "+inf" | "-inf" | "nan" | "+nan" | "-nan") { return true; }
    // simple float pattern
    let mut has_digit = false;
    let mut has_dot_or_exp = false;
    let mut chars = t.chars().peekable();
    if let Some(c) = chars.peek() { if *c == '+' || *c == '-' { chars.next(); } }
    for c in chars {
        if c.is_ascii_digit() { has_digit = true; }
        else if c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' { has_dot_or_exp = true; }
        else { return false; }
    }
    has_digit && has_dot_or_exp && t.parse::<f64>().is_ok()
}

fn is_toml_datetime(tok: &str) -> bool {
    // crude: contains '-' or ':' and digits, and looks like RFC3339/date/time
    if tok.len() >= 8 && tok.chars().filter(|c| *c == '-').count() >= 1 && tok.chars().any(|c| c.is_ascii_digit()) {
        // TOML dates start with a digit and have - or :
        let first = tok.chars().next().unwrap_or(' ');
        if first.is_ascii_digit() && (tok.contains('-') || tok.contains(':')) {
            // ensure characters are plausible datetime chars
            return tok.chars().all(|c| c.is_ascii_digit() || matches!(c, '-'|':'|'T'|'Z'|'.'|'+'|' '));
        }
    }
    false
}

// ---------------- Config building ----------------

pub fn config_from_toml(text: &str) -> Result<FileConfig, ()> {
    let text = text.strip_prefix('\u{feff}').unwrap_or(text);
    let mut parser = TomlParser { chars: text.chars().collect(), pos: 0 };
    let top = parser.parse_document()?;
    let mut cfg = FileConfig::default();
    for (key, value) in &top {
        // key may be quoted like "\"reverse\"" - normalize by stripping quotes
        let normalized = normalize_key(key);
        match normalized.as_str() {
            "reverse" => cfg.reverse = expect_bool(value)?,
            "display-full-paths" => cfg.display_full_paths = expect_bool(value)?,
            "display-apparent-size" => cfg.display_apparent_size = expect_bool(value)?,
            "no-colors" => cfg.no_colors = expect_bool(value)?,
            "no-bars" => cfg.no_bars = expect_bool(value)?,
            "skip-total" => cfg.skip_total = expect_bool(value)?,
            "ignore-hidden" => cfg.ignore_hidden = expect_bool(value)?,
            "output-format" => cfg.output_format = Some(expect_string(value)?),
            "number-of-lines" => cfg.number_of_lines = Some(expect_usize(value)?),
            "depth" => cfg.depth = Some(expect_usize(value)?),
            "only-dir" => cfg.only_dir = expect_bool(value)?,
            "only-file" => cfg.only_file = expect_bool(value)?,
            "screen-reader" => cfg.screen_reader = expect_bool(value)?,
            "bars-on-right" => cfg.bars_on_right = expect_bool(value)?,
            "min-size" => cfg.min_size = Some(expect_string(value)?),
            "output-json" => cfg.output_json = expect_bool(value)?,
            "force-colors" => cfg.force_colors = expect_bool(value)?,
            "print-errors" => cfg.print_errors = expect_bool(value)?,
            "threads" => cfg.threads = Some(expect_usize(value)?),
            "stack-size" => cfg.stack_size = Some(expect_usize(value)?),
            "files-from" => cfg.files_from = Some(expect_string(value)?),
            "files0-from" => cfg.files0_from = Some(expect_string(value)?),
            _ => {}
        }
    }
    Ok(cfg)
}

fn normalize_key(key: &str) -> String {
    let k = key.trim();
    if (k.starts_with('"') && k.ends_with('"') && k.len() >= 2) || (k.starts_with('\'') && k.ends_with('\'') && k.len() >= 2) {
        k[1..k.len() - 1].to_string()
    } else {
        k.to_string()
    }
}

fn expect_bool(v: &TomlValue) -> Result<bool, ()> {
    match v { TomlValue::Bool(b) => Ok(*b), _ => Err(()) }
}
fn expect_string(v: &TomlValue) -> Result<String, ()> {
    match v { TomlValue::Str(s) => Ok(s.clone()), _ => Err(()) }
}
fn expect_usize(v: &TomlValue) -> Result<usize, ()> {
    match v {
        TomlValue::Int(i) if *i >= 0 && *i <= usize::MAX as i128 => Ok(*i as usize),
        _ => Err(()),
    }
}

// ---------------- Loading ----------------

enum LoadResult {
    Config(FileConfig),
    None,
}

fn load_config_file_internal(path: &Path, explicit: bool) -> LoadResult {
    if explicit && !path.exists() {
        eprintln!("Config file {:?} doesn't exists", path);
        return LoadResult::None;
    }
    if !explicit && !path.exists() {
        return LoadResult::None;
    }
    // extension check
    let ext_ok = match path.extension() {
        Some(ext) => ext.to_string_lossy().to_lowercase() == "toml",
        None => false,
    };
    if !ext_ok {
        if explicit {
            eprintln!("Ignoring invalid config file '{}': don't know how to parse file", path.display());
        }
        return LoadResult::None;
    }
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            if explicit {
                eprintln!("Ignoring invalid config file '{}': couldn't read config file", path.display());
            }
            return LoadResult::None;
        }
    };
    match config_from_toml(&content) {
        Ok(cfg) => LoadResult::Config(cfg),
        Err(_) => {
            if explicit {
                eprintln!("Ignoring invalid config file '{}': couldn't parse TOML file", path.display());
            }
            LoadResult::None
        }
    }
}

pub fn load_config(cli_config: Option<&str>) -> FileConfig {
    if let Some(path_str) = cli_config {
        let path = PathBuf::from(path_str);
        match load_config_file_internal(&path, true) {
            LoadResult::Config(c) => return c,
            LoadResult::None => return FileConfig::default(),
        }
    }
    // default locations: ~/.dust.toml then ~/.config/dust/config.toml
    if let Some(home) = home_dir() {
        let first = home.join(".dust.toml");
        if let LoadResult::Config(c) = load_config_file_internal(&first, false) {
            return c;
        }
        let second = home.join(".config").join("dust").join("config.toml");
        if let LoadResult::Config(c) = load_config_file_internal(&second, false) {
            return c;
        }
    }
    FileConfig::default()
}

pub fn home_dir() -> Option<PathBuf> {
    if let Ok(home) = std::env::var("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home));
        }
    }
    // fallback: parse /etc/passwd for current uid
    let uid = unsafe { libc_getuid() };
    if let Ok(passwd) = std::fs::read_to_string("/etc/passwd") {
        for line in passwd.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 6 {
                if let Ok(entry_uid) = parts[2].parse::<u32>() {
                    if entry_uid == uid {
                        return Some(PathBuf::from(parts[5]));
                    }
                }
            }
        }
    }
    None
}

