// ---------- time filters ----------

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum TimeSign { Plus, Minus, Exact }

#[derive(Debug, Clone, Copy)]
pub struct TimeCond {
    pub sign: TimeSign,
    pub days: u64,
}

pub fn parse_time_cond(s: &str) -> Result<TimeCond, ()> {
    // Caller handles panic emulation on Err.
    let (sign, rest) = if let Some(r) = s.strip_prefix('+') {
        (TimeSign::Plus, r)
    } else if let Some(r) = s.strip_prefix('-') {
        (TimeSign::Minus, r)
    } else {
        (TimeSign::Exact, s)
    };
    if rest.is_empty() { return Err(()); }
    // rest must parse as u64 (Rust parse allows leading +)
    match rest.parse::<u64>() {
        Ok(v) => Ok(TimeCond { sign, days: v }),
        Err(_) => Err(()),
    }
}

#[derive(Debug, Clone)]
pub struct TimeFilters {
    pub mtime: Option<TimeCond>,
    pub atime: Option<TimeCond>,
    pub ctime: Option<TimeCond>,
    pub now_time: SystemTime,
    pub now_date_days: i64,
}

impl TimeFilters {
    pub fn new(mtime: Option<TimeCond>, atime: Option<TimeCond>, ctime: Option<TimeCond>) -> TimeFilters {
        let now = SystemTime::now();
        let secs = match now.duration_since(UNIX_EPOCH) { Ok(d) => d.as_secs() as i64, Err(_) => 0 };
        let local = timeutil::local_from_unix(secs);
        let days = timeutil::days_from_civil(local.year, local.mon, local.mday);
        TimeFilters { mtime, atime, ctime, now_time: now, now_date_days: days }
    }

    fn passes_one(&self, cond: TimeCond, file_secs: i64, file_nsec: i64) -> bool {
        match cond.sign {
            TimeSign::Exact | TimeSign::Minus => {
                let local = timeutil::local_from_unix(file_secs);
                let file_days = timeutil::days_from_civil(local.year, local.mon, local.mday);
                let delta: i128 = self.now_date_days as i128 - file_days as i128;
                if cond.sign == TimeSign::Exact {
                    delta == cond.days as i128 + 1
                } else {
                    delta <= cond.days as i128
                }
            }
            TimeSign::Plus => {
                // file_time < now - (days+1) days
                let Some(sub_days) = cond.days.checked_add(1) else { return false; };
                let Some(dur_secs) = sub_days.checked_mul(86400) else { return false; };
                let Some(threshold) = self.now_time.checked_sub(Duration::from_secs(dur_secs)) else { return false; };
                let file_time = timeutil::system_time_from_signed(file_secs, file_nsec);
                file_time < threshold
            }
        }
    }

    pub fn passes(&self, md: &fs::Metadata) -> bool {
        if let Some(c) = self.mtime {
            if !self.passes_one(c, md.mtime(), md.mtime_nsec()) { return false; }
        }
        if let Some(c) = self.atime {
            if !self.passes_one(c, md.atime(), md.atime_nsec()) { return false; }
        }
        if let Some(c) = self.ctime {
            if !self.passes_one(c, md.ctime(), md.ctime_nsec()) { return false; }
        }
        true
    }
}

// ---------- build options / context ----------

pub struct BuildOpts {
    pub apparent: bool,
    pub deref: bool,
    pub limit_fs: bool,
    pub filecount: bool,
    pub filetime: Option<FileTimeKind>,
    pub filters: Vec<Regex>,
    pub invert_filters: Vec<Regex>,
    pub time_filters: TimeFilters,
    pub ignore_hidden: bool,
    pub ignore_directories: Vec<PathBuf>, // raw -X arguments
}

pub struct ProgressShared {
    pub count: std::sync::atomic::AtomicU64,
    pub size: std::sync::atomic::AtomicU64,
    pub current_path: std::sync::Mutex<String>,
}

pub struct BuildCtx {
    pub opts: BuildOpts,
    pub bad_paths: Vec<String>,
    pub perm_paths: Vec<String>,
    pub progress: Option<std::sync::Arc<ProgressShared>>,
}

impl BuildCtx {
    fn progress_add(&self, size: u64) {
        if let Some(p) = &self.progress {
            p.count.fetch_add(1, AtomicOrdering::SeqCst);
            p.size.fetch_add(size, AtomicOrdering::SeqCst);
        }
    }
    fn progress_set_path(&self, path: &str) {
        if let Some(p) = &self.progress {
            if let Ok(mut g) = p.current_path.lock() { *g = path.to_string(); }
        }
    }
}

fn filetime_abs_secs(md: &fs::Metadata, kind: FileTimeKind) -> u64 {
    match kind {
        FileTimeKind::M => md.modified().map(|t| timeutil::system_time_abs_secs(t)).unwrap_or(0),
        FileTimeKind::A => md.accessed().map(|t| timeutil::system_time_abs_secs(t)).unwrap_or(0),
        FileTimeKind::C => {
            let secs = md.ctime();
            let ft = timeutil::system_time_from_signed(secs, md.ctime_nsec());
            timeutil::system_time_abs_secs(ft)
        }
    }
}

pub fn aggregate_size(filetime: Option<FileTimeKind>, own: u64, children: &[Node]) -> u64 {
    if filetime.is_some() {
        let mut max = own;
        for c in children { if c.size > max { max = c.size; } }
        max
    } else {
        own + children.iter().map(|c| c.size).sum::<u64>()
    }
}

fn passes_filters(ctx: &BuildCtx, path: &Path, md: &fs::Metadata) -> bool {
    let path_str = path.to_string_lossy();
    if !ctx.opts.filters.is_empty() {
        if !ctx.opts.filters.iter().any(|r| r.is_match(&path_str)) { return false; }
    }
    if !ctx.opts.invert_filters.is_empty() {
        if ctx.opts.invert_filters.iter().any(|r| r.is_match(&path_str)) { return false; }
    }
    if !ctx.opts.time_filters.passes(md) { return false; }
    true
}

fn is_ignored_path(child_path: &Path, ignored: &[PathBuf]) -> bool {
    if ignored.is_empty() { return false; }
    match fs::canonicalize(child_path) {
        Ok(canon) => ignored.iter().any(|ig| child_path.starts_with(ig) || canon.starts_with(ig)),
        Err(_) => false,
    }
}

pub fn build_root(ctx: &mut BuildCtx, input_path: &Path) -> Option<Node> {
    let normalized = normalize_path(input_path);
    ctx.progress_set_path(&normalized.to_string_lossy());
    // root device for limit-filesystem: prefer followed metadata
    let root_dev: Option<u64> = match fs::metadata(&normalized) {
        Ok(md) => Some(md.dev()),
        Err(_) => match fs::symlink_metadata(&normalized) { Ok(md) => Some(md.dev()), Err(_) => None },
    };
    let ignored: Vec<PathBuf> = ctx.opts.ignore_directories.iter().map(|arg| normalized.join(arg)).collect();
    let node = build_node(ctx, &normalized, true, root_dev, &ignored);
    // Special root types that are neither file nor dir (following) are reported
    // as bad paths, even though a node may have been built for them.
    if node.is_some() {
        let followed_ok = {
            let is_file = normalized.is_file();
            let is_dir = normalized.is_dir();
            is_file || is_dir
        };
        if !followed_ok {
            let s = normalized.display().to_string();
            if !ctx.bad_paths.contains(&s) {
                ctx.bad_paths.push(s);
            }
        }
    }
    node
}

fn build_node(ctx: &mut BuildCtx, path: &Path, is_root: bool, root_dev: Option<u64>, ignored_paths: &[PathBuf]) -> Option<Node> {
    let md_result = if ctx.opts.deref { fs::metadata(path) } else { fs::symlink_metadata(path) };
    let md = match md_result {
        Ok(m) => m,
        Err(_) => {
            ctx.bad_paths.push(path.display().to_string());
            return None;
        }
    };
    // limit filesystem
    if ctx.opts.limit_fs && !is_root {
        if let Some(rd) = root_dev {
            if md.dev() != rd { return None; }
        }
    }
    let passes = passes_filters(ctx, path, &md);
    // own raw value
    let lstat_is_file = fs::symlink_metadata(path).map(|m| m.file_type().is_file()).unwrap_or(false);
    let own_raw: u64 = if ctx.opts.filecount {
        if is_root { 0 } else if lstat_is_file { 1 } else { 0 }
    } else if let Some(kind) = ctx.opts.filetime {
        filetime_abs_secs(&md, kind)
    } else if ctx.opts.apparent {
        md.len()
    } else {
        md.blocks() * 512
    };
    let own_effective = if passes { own_raw } else { 0 };
    ctx.progress_add(own_raw);

    // traversal classification
    let traversal_is_dir = if is_root {
        fs::metadata(path).map(|m| m.is_dir()).unwrap_or(false)
    } else if ctx.opts.deref {
        md.is_dir()
    } else {
        md.file_type().is_dir()
    };
    let is_file_for_types = fs::metadata(path).map(|m| m.is_file()).unwrap_or(false);

    if traversal_is_dir {
        // read directory
        let mut entries: Vec<PathBuf> = Vec::new();
        match fs::read_dir(path) {
            Ok(rd) => {
                let mut names: Vec<std::ffi::OsString> = Vec::new();
                for entry in rd {
                    match entry {
                        Ok(e) => names.push(e.file_name()),
                        Err(_) => {}
                    }
                }
                names.sort();
                for name in names {
                    entries.push(path.join(&name));
                }
            }
            Err(_) => {
                ctx.perm_paths.push(path.display().to_string());
            }
        }
        let mut children: Vec<Node> = Vec::new();
        for child_path in entries {
            // hidden check
            if ctx.opts.ignore_hidden {
                if let Some(name) = child_path.file_name() {
                    if name.to_string_lossy().starts_with('.') { continue; }
                }
            }
            if is_ignored_path(&child_path, ignored_paths) { continue; }
            if let Some(child) = build_node(ctx, &child_path, false, root_dev, ignored_paths) {
                children.push(child);
            }
        }
        children.sort_by(node_cmp_desc);
        if !is_root && !passes && children.is_empty() {
            return None;
        }
        let size = aggregate_size(ctx.opts.filetime, own_effective, &children);
        let mut node = Node::new(path.to_path_buf(), size, own_effective);
        node.children = children;
        node.inode_key = Some((md.dev(), md.ino()));
        node.is_file_for_types = is_file_for_types;
        node.traversal_is_dir = true;
        return Some(node);
    } else {
        if !is_root && !passes {
            return None;
        }
        let mut node = Node::new(path.to_path_buf(), own_effective, own_effective);
        node.inode_key = Some((md.dev(), md.ino()));
        node.is_file_for_types = is_file_for_types;
        node.traversal_is_dir = false;
        return Some(node);
    }
}

// ---------- dedup (hardlink) post-process ----------

pub fn dedup_tree(top: &mut Node, apparent: bool, filetime: Option<FileTimeKind>) {
    if apparent { return; }
    let mut visited: HashSet<(u64, u64)> = HashSet::new();
    dedup_node(top, &mut visited, filetime, true);
}

fn dedup_node(node: &mut Node, visited: &mut HashSet<(u64, u64)>, filetime: Option<FileTimeKind>, is_top: bool) -> bool {
    if !is_top {
        if let Some(key) = node.inode_key {
            if visited.contains(&key) { return false; }
            visited.insert(key);
        }
    } else {
        // top may be (total) with no inode, or a single root. If it is a single root with
        // an inode, record it so descendants that duplicate the root are removed.
        if let Some(key) = node.inode_key {
            visited.insert(key);
        }
    }
    // order children: directories first (traversal dirs), then by name ascending
    let mut order: Vec<usize> = (0..node.children.len()).collect();
    order.sort_by(|&a, &b| {
        let ca = &node.children[a];
        let cb = &node.children[b];
        let da = if ca.traversal_is_dir { 0 } else { 1 };
        let db = if cb.traversal_is_dir { 0 } else { 1 };
        da.cmp(&db).then_with(|| ca.name.cmp(&cb.name))
    });
    let mut remove_ids: HashSet<u64> = HashSet::new();
    for idx in order {
        let child_id = node.children[idx].id;
        let keep = {
            let child = &mut node.children[idx];
            dedup_node(child, visited, filetime, false)
        };
        if !keep { remove_ids.insert(child_id); }
    }
    node.children.retain(|c| !remove_ids.contains(&c.id));
    node.size = aggregate_size(filetime, node.own_size, &node.children);
    true
}

// ---------- transforms ----------

pub fn prune_depth(node: &mut Node, max_depth: Option<usize>) {
    if let Some(d) = max_depth {
        prune_depth_rec(node, 0, d);
    }
}

fn prune_depth_rec(node: &mut Node, depth: usize, max: usize) {
    if depth >= max {
        node.children.clear();
        return;
    }
    for child in &mut node.children {
        prune_depth_rec(child, depth + 1, max);
    }
}

pub fn collapse_tree(root: &mut Node, root_path: &Path, collapse_args: &[PathBuf]) {
    if collapse_args.is_empty() { return; }
    collapse_rec(root, root_path, collapse_args, true);
}

fn collapse_rec(node: &mut Node, root_path: &Path, args: &[PathBuf], is_root: bool) {
    if !is_root {
        for arg in args {
            let target = root_path.join(arg);
            if node.name == target {
                node.children.clear();
                return;
            }
        }
    }
    for child in &mut node.children {
        collapse_rec(child, root_path, args, false);
    }
}

pub fn only_file_tree(top: &mut Node) {
    let mut leaves: Vec<Node> = Vec::new();
    let old_children = std::mem::take(&mut top.children);
    for child in old_children {
        collect_leaves(child, &mut leaves);
    }
    leaves.sort_by(node_cmp_desc);
    top.children = leaves;
}

fn collect_leaves(node: Node, out: &mut Vec<Node>) {
    if node.children.is_empty() {
        out.push(node);
    } else {
        for child in node.children {
            collect_leaves(child, out);
        }
    }
}

pub fn only_dir_tree(top: &mut Node) {
    let old_children = std::mem::take(&mut top.children);
    let mut kept: Vec<Node> = Vec::new();
    for mut child in old_children {
        if child.name.is_dir() {
            only_dir_tree(&mut child);
            kept.push(child);
        }
    }
    top.children = kept;
}

pub fn prune_min_size(node: &mut Node, min: u64) {
    let old_children = std::mem::take(&mut node.children);
    let mut kept: Vec<Node> = Vec::new();
    for mut child in old_children {
        if child.size > min {
            prune_min_size(&mut child, min);
            kept.push(child);
        }
    }
    node.children = kept;
}

// ---------- duplicate root renaming ----------

pub fn display_name_for_path(path: &Path, full_paths: bool) -> String {
    if full_paths {
        return path.to_string_lossy().to_string();
    }
    if let Some(fname) = path.file_name() {
        return fname.to_string_lossy().to_string();
    }
    if let Some(last) = path.components().last() {
        return last.as_os_str().to_string_lossy().to_string();
    }
    path.to_string_lossy().to_string()
}

pub fn rename_duplicate_roots(top: &mut Node) {
    // Groups children of top by display name (non-full-path form)
    let mut groups: HashMap<String, Vec<usize>> = HashMap::new();
    for (idx, child) in top.children.iter().enumerate() {
        let dn = display_name_for_path(&child.name, false);
        groups.entry(dn).or_default().push(idx);
    }
    // component lists for each child (reversed ancestors components after the last)
    for (_name, indices) in groups.iter() {
        if indices.len() < 2 { continue; }
        // component sequences: components of original path, reversed, skipping last component
        let mut seqs: Vec<Vec<String>> = Vec::new();
        for &idx in indices {
            let comps: Vec<String> = top.children[idx].name.components().map(|c| match c {
                Component::RootDir => "/".to_string(),
                Component::CurDir => ".".to_string(),
                Component::ParentDir => "..".to_string(),
                Component::Normal(s) => s.to_string_lossy().to_string(),
                Component::Prefix(p) => p.as_os_str().to_string_lossy().to_string(),
            }).collect();
            // ancestors in order: second-last down to first
            let mut ancestors: Vec<String> = Vec::new();
            if comps.len() >= 2 {
                for k in (0..comps.len() - 1).rev() {
                    ancestors.push(comps[k].clone());
                }
            }
            seqs.push(ancestors);
        }
        let mut positions = vec![0usize; indices.len()];
        loop {
            // check uniqueness by current display names
            let mut names: Vec<String> = indices.iter().map(|&idx| display_name_for_path(&top.children[idx].name, false)).collect();
            let unique = {
                let mut sorted = names.clone();
                sorted.sort();
                sorted.dedup();
                sorted.len() == names.len()
            };
            if unique { break; }
            names.clear();
            let mut any = false;
            for (k, &idx) in indices.iter().enumerate() {
                if positions[k] < seqs[k].len() {
                    let suffix = format!("({})", seqs[k][positions[k]]);
                    let mut new_path_str = top.children[idx].name.to_string_lossy().to_string();
                    new_path_str.push_str(&suffix);
                    top.children[idx].name = PathBuf::from(new_path_str);
                    positions[k] += 1;
                    any = true;
                }
            }
            if !any { break; }
        }
    }
}

// ---------- file types aggregation ----------

pub fn get_extension_key(node: &Node) -> String {
    match node.name.extension() {
        Some(ext) => format!(".{}", ext.to_string_lossy()),
        None => "(no extension)".to_string(),
    }
}

pub fn aggregate_file_types(top: &Node, is_total: bool, effective_lines: usize, filetime: Option<FileTimeKind>, filecount: bool) -> Node {
    let mut map: Vec<(String, u64)> = Vec::new(); // preserve insertion for tie handling; we will sort later
    collect_file_types(top, is_total, &mut map);
    // build group nodes
    let mut groups: Vec<Node> = Vec::new();
    for (key, size) in &map {
        let mut n = Node::new(PathBuf::from(key), *size, *size);
        n.traversal_is_dir = false;
        groups.push(n);
    }
    groups.sort_by(node_cmp_desc);
    let keep_specific = std::cmp::max(1usize, effective_lines.saturating_sub(1));
    let mut children: Vec<Node> = Vec::new();
    if groups.len() > keep_specific {
        let mut others: u64 = 0;
        for (i, g) in groups.into_iter().enumerate() {
            if i < keep_specific { children.push(g); } else { others += g.size; }
        }
        let others_node = Node::new(PathBuf::from("(others)"), others, others);
        children.push(others_node);
    } else {
        children = groups;
    }
    let total_size = if filetime.is_some() {
        children.iter().map(|c| c.size).max().unwrap_or(0)
    } else {
        children.iter().map(|c| c.size).sum()
    };
    let _ = filecount;
    let mut total = Node::new(PathBuf::from("(total)"), total_size, 0);
    total.children = children;
    total
}

fn collect_file_types(node: &Node, is_artificial_total: bool, map: &mut Vec<(String, u64)>) {
    if !is_artificial_total && node.is_file_for_types {
        let key = get_extension_key(node);
        if let Some(entry) = map.iter_mut().find(|(k, _)| *k == key) {
            entry.1 += node.size;
        } else {
            map.push((key, node.size));
        }
        return;
    }
    for child in &node.children {
        collect_file_types(child, false, map);
    }
}

// ---------- selection (largest-first expansion) ----------

#[derive(Eq, PartialEq)]
struct HeapItem {
    size: u64,
    name: PathBuf,
    id: u64,
}
impl Ord for HeapItem {
    fn cmp(&self, other: &Self) -> Ordering {
        self.size.cmp(&other.size).then_with(|| self.name.cmp(&other.name)).then_with(|| self.id.cmp(&other.id))
    }
}
impl PartialOrd for HeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> { Some(self.cmp(other)) }
}

pub fn select_tree(root: &Node, n: usize) -> Node {
    // map id -> node ref
    let mut map: HashMap<u64, &Node> = HashMap::new();
    build_id_map(root, &mut map);
    let mut heap: BinaryHeap<HeapItem> = BinaryHeap::new();
    heap.push(HeapItem { size: root.size, name: root.name.clone(), id: root.id });
    let mut selected: HashSet<u64> = HashSet::new();
    let mut count: usize = 0;
    while let Some(item) = heap.pop() {
        let node = match map.get(&item.id) { Some(n) => *n, None => continue };
        if node.id != root.id {
            if count >= n { break; }
            selected.insert(node.id);
            count += 1;
            if count >= n { break; }
        }
        for child in &node.children {
            heap.push(HeapItem { size: child.size, name: child.name.clone(), id: child.id });
        }
    }
    clone_selected(root, &selected)
}

fn build_id_map<'a>(node: &'a Node, map: &mut HashMap<u64, &'a Node>) {
    map.insert(node.id, node);
    for child in &node.children { build_id_map(child, map); }
}

fn clone_selected(node: &Node, selected: &HashSet<u64>) -> Node {
    let mut new_node = node.clone_without_children();
    new_node.size = node.size;
    for child in &node.children {
        if selected.contains(&child.id) {
            new_node.children.push(clone_selected(child, selected));
        }
    }
    new_node
}
RS"}

