#[allow(clippy::too_many_arguments)]
fn generate_rec(
    node: &Node,
    depth: usize,
    ancestors_sizes: Vec<u64>,
    segments: Vec<bool>,
    is_root: bool,
    is_last_desc: bool,
    opts: &DisplayOpts,
    lines: &mut Vec<Line>,
) {
    // segment for this node's children if it becomes an ancestor
    // root -> false; otherwise -> !is_last_desc
    let segment_for_children = if is_root { false } else { !is_last_desc };
    let line = Line {
        node_id: node.id,
        node_name_path: node.name.clone(),
        size_value: node.size,
        display_name: display_name_clean(node, opts.full_paths),
        depth,
        ancestors_sizes: ancestors_sizes.clone(),
        segments: segments.clone(),
        connector_first_rev: if is_root { '└' } else if is_last_desc { '└' } else { '├' },
        connector_has_children: !node.children.is_empty(),
        is_last_desc,
        is_root,
        highlight: false, // filled later by parent logic (root placeholder)
    };
    // We need highlight of node: computed by parent. Store temporarily; parent will set before recursion?
    // Instead, generate with highlight passed in. This function's signature lacks it; we set root true
    // and adjust children after (we will patch in generate_lines wrapper by regenerating with highlight param)
    lines.push(line);
    // children order is already descending in node.children
    let mut child_ancestors = ancestors_sizes.clone();
    child_ancestors.push(node.size);
    let mut child_segments = segments.clone();
    if !is_root || true {
        // child's segments include segment for this node
        // For root, this adds false (spaces). For others, segment_for_children
        child_segments.push(segment_for_children);
    }
    // The segments for child should be: parent's segments + [segment for parent]
    // But parent's segments are 'segments' argument; above child_segments starts as clone of segments
    // then pushes one. That is correct.
    for (idx, child) in node.children.iter().enumerate() {
        let child_is_last = idx == node.children.len() - 1;
        generate_rec(child, depth + 1, child_ancestors.clone(), child_segments.clone(), false, child_is_last, opts, lines);
    }
}

// We need highlight info: root true, first child (descending) true for each parent.
// Recompute highlights by walking the tree in parallel with lines order (preorder)
fn assign_highlights(root: &Node, lines: &mut [Line]) {
    // lines are preorder; we can walk tree and assign by node id
    let mut map = std::collections::HashMap::new();
    assign_highlights_rec(root, true, &mut map);
    for line in lines.iter_mut() {
        if let Some(v) = map.get(&line.node_id) { line.highlight = *v; }
    }
}

fn assign_highlights_rec(node: &Node, highlight: bool, map: &mut std::collections::HashMap<u64, bool>) {
    map.insert(node.id, highlight);
    for (idx, child) in node.children.iter().enumerate() {
        assign_highlights_rec(child, idx == 0, map);
    }
}

pub fn display_tree(root: &Node, opts: &DisplayOpts) {
    // width assert 142
    if opts.terminal_width <= 7 {
        crate::progress::panic_exit("<unnamed>", "src/display.rs:142:5", "Not enough terminal width");
    }
    let mut stdout = std::io::BufWriter::new(std::io::stdout());
    display_tree_to(root, opts, &mut stdout);
    let _ = stdout.flush();
}

fn display_tree_to(root: &Node, opts: &DisplayOpts, out: &mut dyn Write) {
    let lscolors = if opts.use_colors { Some(LsColors::from_env()) } else { None };
    // generate lines
    let mut lines = generate_lines(root, opts);
    assign_highlights(root, &mut lines);
    if !opts.reverse {
        lines.reverse();
    }
    let total_size = root.size;
    // skip-total adaptation
    if opts.skip_total {
        // remove root line
        lines.retain(|l| !l.is_root);
        for line in lines.iter_mut() {
            if line.depth > 0 { line.depth -= 1; }
            if !line.segments.is_empty() { line.segments.remove(0); }
            if !line.ancestors_sizes.is_empty() { line.ancestors_sizes.remove(0); }
            // root line connector etc stays; a top child's is_root flag is false already
            // But after removal, nodes that were root children should be treated as roots for connector?
            // Their connector is based on is_last_desc and is_root=false; for normal mode connector
            // uses is_last_desc to pick ┌ vs ├, which matches original. Good.
        }
    }

    if opts.screen_reader {
        display_screen_reader(&lines, opts, total_size, &lscolors, out);
        return;
    }

    if opts.filetime.is_some() {
        display_filetime(&lines, opts, total_size, &lscolors, out);
        return;
    }

    // normal/tree mode
    // size strings
    let size_strs: Vec<String> = lines.iter().map(|l| format_display_size(l.size_value, opts, false)).collect();
    let max_size_w = size_strs.iter().map(|s| string_width(s)).max().unwrap_or(0);
    // Build raw prefixes
    struct RawLine {
        idx: usize,
        before_name: String, // size + space + segments + connector + space, colored size applied later (we keep raw for width)
        before_name_width: usize,
        raw: String, // before_name + display_name (uncolored)
    }
    let mut raws: Vec<RawLine> = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let seg_str: String = line.segments.iter().map(|b| if *b { "│ " } else { "  " }).collect();
        let conn = format!("{}{} ", connector_first(line, opts.reverse), connector_second(line, opts.reverse));
        let before = format!("{} {}{}", pad_left(&size_strs[i], max_size_w), seg_str, conn);
        let bw = string_width(&before);
        let raw = format!("{}{}", before, line.display_name);
        raws.push(RawLine { idx: i, before_name: before, before_name_width: bw, raw });
    }
    let max_prefix_w = raws.iter().map(|r| string_width(&r.raw)).max().unwrap_or(0);

    let bars_enabled = !opts.no_percent_bars && opts.terminal_width >= max_prefix_w + 9 && max_prefix_w > 0 || (!opts.no_percent_bars && opts.terminal_width >= max_prefix_w + 9);
    // Note: if there are no lines, bars_enabled irrelevant
    let bar_width = if bars_enabled { opts.terminal_width - max_prefix_w - 8 } else { 0 };

    for raw in &raws {
        let line = &lines[raw.idx];
        // size field coloring needs reconstruction: rebuild before_name with colored size if needed
        let seg_str: String = line.segments.iter().map(|b| if *b { "│ " } else { "  " }).collect();
        let conn = format!("{}{} ", connector_first(line, opts.reverse), connector_second(line, opts.reverse));
        let size_field_plain = pad_left(&size_strs[raw.idx], max_size_w);
        let size_field = if opts.use_colors && line.highlight {
            format!("\x1b[31m{}\x1b[0m", size_field_plain)
        } else { size_field_plain.clone() };
        if bars_enabled {
            // pad name to max prefix
            let name_field_width = max_prefix_w - raw.before_name_width;
            let name_padded = pad_right(&line.display_name, name_field_width);
            let name_display = colorize_name(&lscolors, opts, &line.node_name_path, &name_padded);
            let prefix = format!("{} {}{}", size_field, seg_str, conn);
            // Note: prefix contains size_field (colored) + seg + conn; width-wise same as before_name
            let bar = build_bar(line, total_size, bar_width, opts.bars_on_right);
            let percent = percent_string(line.size_value, total_size);
            let percent_field = format!("{:>4}", percent);
            let _ = writeln!(out, "{}│{} │ {}", format!("{}{}", prefix, name_display), bar, percent_field);
        } else {
            // no bars: possibly truncate
            // compute the uncolored raw line: need before_name with uncolored size for width, but output uses colored size
            let plain_before = format!("{} {}{}", size_field_plain, seg_str, conn);
            let plain_raw = format!("{}{}", plain_before, line.display_name);
            if string_width(&plain_raw) > opts.terminal_width {
                // truncate display name
                let stem_width = string_width(&plain_before);
                if opts.terminal_width < stem_width || opts.terminal_width - stem_width < 2 {
                    // flush before panicking to preserve partial output
                    let _ = out.flush();
                    crate::progress::panic_exit("<unnamed>", "src/display.rs:308:5", "Terminal width not wide enough to draw directory tree");
                }
                let avail = opts.terminal_width - stem_width;
                let truncated = format!("{}..", truncate_by_width(&line.display_name, avail - 2));
                let name_display = colorize_name(&lscolors, opts, &line.node_name_path, &truncated);
                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            } else {
                let name_display = colorize_name(&lscolors, opts, &line.node_name_path, &line.display_name);
                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            }
        }
    }
}

fn colorize_name(lscolors: &Option<LsColors>, opts: &DisplayOpts, path: &PathBuf, text: &str) -> String {
    if !opts.use_colors { return text.to_string(); }
    if let Some(lsc) = lscolors {
        let prefix = lsc.style_prefix_for_path(path);
        return wrap_color(prefix, text);
    }
    text.to_string()
}

fn percent_value(size: u64, total: u64) -> f64 {
    if total == 0 { 0.0 } else { size as f64 * 100.0 / total as f64 }
}

fn percent_string(size: u64, total: u64) -> String {
    format!("{:.0}%", percent_value(size, total))
}

fn build_bar(line: &Line, total: u64, width: usize, bars_on_right: bool) -> String {
    if width == 0 { return String::new(); }
    let mut bar = vec![' '; width];
    let endpoint = |sz: u64| -> usize {
        if total == 0 { 1 } else {
            let v = (sz as u128 * width as u128 + total as u128 - 1) / total as u128;
            let v = v as usize;
            if v == 0 { 1 } else { v }
        }
    };
    let mut current = 0usize;
    let own_end = endpoint(line.size_value).min(width);
    for i in 0..own_end { bar[i] = '█'; }
    current = own_end;
    // ancestors from closest (parent) to farthest (root): ancestors_sizes is root..parent
    for (idx, anc_size) in line.ancestors_sizes.iter().enumerate().rev() {
        let end = endpoint(*anc_size).min(width);
        if end > current {
            let ch = match idx {
                0 => ' ',
                1 => '░',
                2 => '▒',
                _ => '▓',
            };
            for i in current..end { bar[i] = ch; }
            current = end;
        }
        if current >= width { break; }
    }
    let s: String = bar.into_iter().collect();
    if bars_on_right {
        s.chars().rev().collect()
    } else { s }
}

fn display_screen_reader(lines: &[Line], opts: &DisplayOpts, total: u64, lscolors: &Option<LsColors>, out: &mut dyn Write) {
    if lines.is_empty() { return; }
    let max_name_w = lines.iter().map(|l| string_width(&l.display_name)).max().unwrap_or(0);
    let size_strs: Vec<String> = lines.iter().map(|l| format_display_size(l.size_value, opts, false)).collect();
    let max_size_w = size_strs.iter().map(|s| string_width(s)).max().unwrap_or(0);
    for (i, line) in lines.iter().enumerate() {
        let name_padded = pad_right(&line.display_name, max_name_w);
        let name_display = colorize_name(lscolors, opts, &line.node_name_path, &name_padded);
        let size_field_plain = pad_left(&size_strs[i], max_size_w);
        let size_field = if opts.use_colors && line.highlight {
            format!("\x1b[31m{}\x1b[0m", size_field_plain)
        } else { size_field_plain };
        let percent_field = format!("{:>4}", percent_string(line.size_value, total));
        let _ = writeln!(out, "{} {} {} {}", name_display, line.depth, size_field, percent_field);
    }
}

fn display_filetime(lines: &[Line], opts: &DisplayOpts, total: u64, lscolors: &Option<LsColors>, out: &mut dyn Write) {
    let _ = total;
    // size strings (timestamp or count if filecount)
    let size_strs: Vec<String> = lines.iter().map(|l| format_display_size(l.size_value, opts, false)).collect();
    let max_size_w = size_strs.iter().map(|s| string_width(s)).max().unwrap_or(0);
    struct Raw { idx: usize, before_name: String, before_width: usize, raw: String }
    let mut raws = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let seg_str: String = line.segments.iter().map(|b| if *b { "│ " } else { "  " }).collect();
        let conn = format!("{}{}", connector_first(line, opts.reverse), connector_second(line, opts.reverse));
        let before = format!("{} {}{}", pad_left(&size_strs[i], max_size_w), seg_str, conn);
        let bw = string_width(&before);
        let raw = format!("{}{}", before, line.display_name);
        raws.push(Raw { idx: i, before_name: before, before_width: bw, raw });
    }
    let max_w = raws.iter().map(|r| string_width(&r.raw)).max().unwrap_or(0);
    let padded_mode = opts.terminal_width >= max_w + 10;
    for raw in &raws {
        let line = &lines[raw.idx];
        let seg_str: String = line.segments.iter().map(|b| if *b { "│ " } else { "  " }).collect();
        let conn = format!("{}{}", connector_first(line, opts.reverse), connector_second(line, opts.reverse));
        let size_field_plain = pad_left(&size_strs[raw.idx], max_size_w);
        let size_field = if opts.use_colors && line.highlight {
            format!("\x1b[31m{}\x1b[0m", size_field_plain)
        } else { size_field_plain.clone() };
        let prefix_plain = format!("{} {}{}", size_field_plain, seg_str, conn);
        if padded_mode {
            let name_field_width = max_w - raw.before_width;
            let name_padded = pad_right(&line.display_name, name_field_width);
            let name_display = colorize_name(lscolors, opts, &line.node_name_path, &name_padded);
            let prefix = format!("{} {}{}", size_field, seg_str, conn);
            let _ = writeln!(out, "{}{}", prefix, name_display);
        } else {
            // truncate to terminal_width - 1 if needed
            let target = opts.terminal_width.saturating_sub(1);
            let plain_raw = format!("{}{}", prefix_plain, line.display_name);
            if string_width(&plain_raw) > target {
                let stem_width = string_width(&prefix_plain);
                if target < stem_width || target - stem_width < 2 {
                    let _ = out.flush();
                    crate::progress::panic_exit("<unnamed>", "src/display.rs:308:5", "Terminal width not wide enough to draw directory tree");
                }
                let avail = target - stem_width;
                let truncated = format!("{}..", truncate_by_width(&line.display_name, avail - 2));
                let name_display = colorize_name(lscolors, opts, &line.node_name_path, &truncated);
                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            } else {
                let name_display = colorize_name(lscolors, opts, &line.node_name_path, &line.display_name);
                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            }
        }
    }
}

// ---------- JSON ----------

pub fn node_to_json_string(root: &Node, opts: &DisplayOpts) -> Result<String, ()> {
    // Build JSON manually with serde-like escaping. Validate name UTF-8 strictly.
    let mut s = String::new();
    write_json_node(root, opts, &mut s)?;
    Ok(s)
}

fn json_escape_into(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

fn write_json_node(node: &Node, opts: &DisplayOpts, out: &mut String) -> Result<(), ()> {
    // name must be valid UTF-8 (serde Path serialization errors otherwise)
    let name_str = match node.name.to_str() {
        Some(s) => s.to_string(),
        None => return Err(()),
    };
    let size_str = if opts.filecount { node.size.to_string() } else { format_size(node.size, &opts.output_format, false) };
    out.push_str("{\"size\":");
    json_escape_into(&size_str, out);
    out.push_str(",\"name\":");
    json_escape_into(&name_str, out);
    out.push_str(",\"children\":[");
    for (i, child) in node.children.iter().enumerate() {
        if i > 0 { out.push(','); }
        write_json_node(child, opts, out)?;
    }
    out.push_str("]}");
    Ok(())
}
