    let bars_enabled = !opts.no_percent_bars && opts.terminal_width >= max_prefix_w + 9 && max_prefix_w > 0 || (!opts.no_percent_bars && opts.terminal_width >= max_prefix_w + 9);
    // Note: if there are no lines, bars_enabled irrelevant
    let bar_width = if bars_enabled { opts.terminal_width - max_prefix_w - 8 } else { 0 };

    for raw in &raws {
        let line = &lines[raw.idx];
        // size field coloring needs reconstruction: rebuild before_name with colored size if needed
        let seg_str: String = line.segments.iter().map(|b| if *b { "│ " } else { "  " }).collect();
        let conn = format!("{}{} ", connector_first(line, opts.reverse), connector_second(line, opts.reverse));
        let size_field_plain = pad_left(&size_strs[raw.idx], max_size_w);
        let size_field = if opts.use_colors && line.highlight {
            format!("\x1b[31m{}\x1b[0m", size_field_plain)
        } else { size_field_plain.clone() };
