                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            } else {
                let name_display = colorize_name(&lscolors, opts, &line.node_name_path, &line.display_name);
                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            }
        }
    }
}

fn colorize_name(lscolors: &Option<LsColors>, opts: &DisplayOpts, path: &PathBuf, text: &str) -> String {
    if !opts.use_colors { return text.to_string(); }
    if let Some(lsc) = lscolors {
        let prefix = lsc.style_prefix_for_path(path);
        return wrap_color(prefix, text);
    }
    text.to_string()
}

fn percent_value(size: u64, total: u64) -> f64 {
    if total == 0 { 0.0 } else { size as f64 * 100.0 / total as f64 }
}

fn percent_string(size: u64, total: u64) -> String {
    format!("{:.0}%", percent_value(size, total))
}

fn build_bar(line: &Line, total: u64, width: usize, bars_on_right: bool) -> String {
    if width == 0 { return String::new(); }
    let mut bar = vec![' '; width];
    let endpoint = |sz: u64| -> usize {
        if total == 0 { 1 } else {
            let v = (sz as u128 * width as u128 + total as u128 - 1) / total as u128;
            let v = v as usize;
            if v == 0 { 1 } else { v }
        }
    };
    let mut current = 0usize;
    let own_end = endpoint(line.size_value).min(width);
    for i in 0..own_end { bar[i] = '█'; }
    current = own_end;
    // ancestors from closest (parent) to farthest (root): ancestors_sizes is root..parent
    for (idx, anc_size) in line.ancestors_sizes.iter().enumerate().rev() {
        let end = endpoint(*anc_size).min(width);
        if end > current {
            let ch = match idx {
                0 => ' ',
                1 => '░',
                2 => '▒',
                _ => '▓',
            };
            for i in current..end { bar[i] = ch; }
            current = end;
        }
        if current >= width { break; }
    }
    let s: String = bar.into_iter().collect();
    if bars_on_right {
        s.chars().rev().collect()
    } else { s }
}

fn display_screen_reader(lines: &[Line], opts: &DisplayOpts, total: u64, lscolors: &Option<LsColors>, out: &mut dyn Write) {
    if lines.is_empty() { return; }
    let max_name_w = lines.iter().map(|l| string_width(&l.display_name)).max().unwrap_or(0);
    let size_strs: Vec<String> = lines.iter().map(|l| format_display_size(l.size_value, opts, false)).collect();
    let max_size_w = size_strs.iter().map(|s| string_width(s)).max().unwrap_or(0);
    for (i, line) in lines.iter().enumerate() {
        let name_padded = pad_right(&line.display_name, max_name_w);
        let name_display = colorize_name(lscolors, opts, &line.node_name_path, &name_padded);
        let size_field_plain = pad_left(&size_strs[i], max_size_w);
        let size_field = if opts.use_colors && line.highlight {
            format!("\x1b[31m{}\x1b[0m", size_field_plain)
        } else { size_field_plain };
        let percent_field = format!("{:>4}", percent_string(line.size_value, total));
        let _ = writeln!(out, "{} {} {} {}", name_display, line.depth, size_field, percent_field);
    }
}

fn display_filetime(lines: &[Line], opts: &DisplayOpts, total: u64, lscolors: &Option<LsColors>, out: &mut dyn Write) {
    let _ = total;
    // size strings (timestamp or count if filecount)
    let size_strs: Vec<String> = lines.iter().map(|l| format_display_size(l.size_value, opts, false)).collect();
    let max_size_w = size_strs.iter().map(|s| string_width(s)).max().unwrap_or(0);
    struct Raw { idx: usize, before_name: String, before_width: usize, raw: String }
    let mut raws = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let seg_str: String = line.segments.iter().map(|b| if *b { "│ " } else { "  " }).collect();
        let conn = format!("{}{}", connector_first(line, opts.reverse), connector_second(line, opts.reverse));
        let before = format!("{} {}{}", pad_left(&size_strs[i], max_size_w), seg_str, conn);
        let bw = string_width(&before);
        let raw = format!("{}{}", before, line.display_name);
        raws.push(Raw { idx: i, before_name: before, before_width: bw, raw });
    }
    let max_w = raws.iter().map(|r| string_width(&r.raw)).max().unwrap_or(0);
    let padded_mode = opts.terminal_width >= max_w + 10;
    for raw in &raws {
        let line = &lines[raw.idx];
        let seg_str: String = line.segments.iter().map(|b| if *b { "│ " } else { "  " }).collect();
        let conn = format!("{}{}", connector_first(line, opts.reverse), connector_second(line, opts.reverse));
        let size_field_plain = pad_left(&size_strs[raw.idx], max_size_w);
        let size_field = if opts.use_colors && line.highlight {
            format!("\x1b[31m{}\x1b[0m", size_field_plain)
        } else { size_field_plain.clone() };
        let prefix_plain = format!("{} {}{}", size_field_plain, seg_str, conn);
        if padded_mode {
            let name_field_width = max_w - raw.before_width;
            let name_padded = pad_right(&line.display_name, name_field_width);
            let name_display = colorize_name(lscolors, opts, &line.node_name_path, &name_padded);
            let prefix = format!("{} {}{}", size_field, seg_str, conn);
            let _ = writeln!(out, "{}{}", prefix, name_display);
        } else {
            // truncate to terminal_width - 1 if needed
            let target = opts.terminal_width.saturating_sub(1);
            let plain_raw = format!("{}{}", prefix_plain, line.display_name);
            if string_width(&plain_raw) > target {
                let stem_width = string_width(&prefix_plain);
                if target < stem_width || target - stem_width < 2 {
                    let _ = out.flush();
                    crate::progress::panic_exit("<unnamed>", "src/display.rs:308:5", "Terminal width not wide enough to draw directory tree");
                }
                let avail = target - stem_width;
                let truncated = format!("{}..", truncate_by_width(&line.display_name, avail - 2));
                let name_display = colorize_name(lscolors, opts, &line.node_name_path, &truncated);
                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            } else {
                let name_display = colorize_name(lscolors, opts, &line.node_name_path, &line.display_name);
                let prefix = format!("{} {}{}", size_field, seg_str, conn);
                let _ = writeln!(out, "{}{}", prefix, name_display);
            }
        }
    }
}

// ---------- JSON ----------

pub fn node_to_json_string(root: &Node, opts: &DisplayOpts) -> Result<String, ()> {
    // Build JSON manually with serde-like escaping. Validate name UTF-8 strictly.
    let mut s = String::new();
    write_json_node(root, opts, &mut s)?;
    Ok(s)
}

fn json_escape_into(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

fn write_json_node(node: &Node, opts: &DisplayOpts, out: &mut String) -> Result<(), ()> {
    // name must be valid UTF-8 (serde Path serialization errors otherwise)
    let name_str = match node.name.to_str() {
        Some(s) => s.to_string(),
        None => return Err(()),
    };
    let size_str = if opts.filecount { node.size.to_string() } else { format_size(node.size, &opts.output_format, false) };
    out.push_str("{\"size\":");
    json_escape_into(&size_str, out);
    out.push_str(",\"name\":");
    json_escape_into(&name_str, out);
    out.push_str(",\"children\":[");
    for (i, child) in node.children.iter().enumerate() {
        if i > 0 { out.push(','); }
        write_json_node(child, opts, out)?;
    }
    out.push_str("]}");
    Ok(())
}
