    if root_nodes.len() == 1 {
        top = root_nodes.into_iter().next().unwrap();
        is_total = false;
    } else {
        is_total = true;
        let children = root_nodes;
        let total_size = tree::aggregate_size(eff.filetime, 0, &children);
