    if is_total && !eff.full_paths {
        tree::rename_duplicate_roots(&mut top);
    }

    // Terminal detection for later display options (height/width/colors)
    let detected_term = term::terminal_size();

    // Effective number of lines
    let effective_lines: usize = if let Some(n) = eff.number_of_lines {
        n
    } else {
        let height: usize = detected_term.map(|(_, rows)| rows as usize).unwrap_or(24);
        std::cmp::max(20usize, height.saturating_sub(10))
    };

    // File-types path
    let final_tree: Node;
    if eff.file_types {
        let mut ft = tree::aggregate_file_types(&top, is_total, effective_lines, eff.filetime, eff.filecount);
        if eff.only_file {
            tree::only_file_tree(&mut ft);
        }
        if eff.only_dir {
            tree::only_dir_tree(&mut ft);
        }
        final_tree = ft;
    } else {
        let mut t = top;
        if eff.only_file {
            tree::only_file_tree(&mut t);
        }
        if eff.only_dir {
            tree::only_dir_tree(&mut t);
        }
        if eff.min_size_present {
            if let Some(min) = eff.min_size {
                tree::prune_min_size(&mut t, min);
            }
        }
        // selection
        let selected = tree::select_tree(&t, effective_lines);
        final_tree = selected;
    }

    progress.stop();

    // Error messages before output
    let has_bad = !ctx.bad_paths.is_empty();
    if has_bad {
        eprintln!("No such file or directory: {}", ctx.bad_paths.join(", "));
    }
    print_perm_errors(&ctx, &eff);
    if has_bad && final_tree.children.is_empty() {
        return 1;
    }

    // Output
    if eff.output_json {
        let display_opts = make_display_opts(&eff, detected_term);
        match display::node_to_json_string(&final_tree, &display_opts) {
            Ok(s) => {
                println!("{}", s);
                0
            }
            Err(_) => {
                progress::panic_exit("<unnamed>", "src/main.rs:328:53", "called `Result::unwrap()` on an `Err` value: Error(\"path contains invalid UTF-8 characters\", line: 0, column: 0)");
            }
        }
    } else {
        let display_opts = make_display_opts(&eff, detected_term);
        display::display_tree(&final_tree, &display_opts);
        0
    }
}

fn print_perm_errors(ctx: &BuildCtx, eff: &Effective) {
    if ctx.perm_paths.is_empty() { return; }
    if eff.print_errors {
        eprintln!("Did not have permissions for directories: {}", ctx.perm_paths.join(", "));
    } else {
        eprintln!("Did not have permissions for all directories (add --print-errors to see errors)");
    }
}

fn make_display_opts(eff: &Effective, detected_term: Option<(u16, u16)>) -> display::DisplayOpts {
    let terminal_width: usize = if let Some(w) = eff.terminal_width {
        w
    } else if let Some((cols, _)) = detected_term {
        cols as usize
    } else {
        80
    };
    let use_colors = if eff.force_colors {
        true
    } else if eff.no_colors {
        false
    } else if std::env::var_os("NO_COLOR").is_some() {
        false
    } else {
        detected_term.is_some()
    };
    display::DisplayOpts {
        reverse: eff.reverse,
        full_paths: eff.full_paths,
        no_percent_bars: eff.no_percent_bars,
        bars_on_right: eff.bars_on_right,
        screen_reader: eff.screen_reader,
        skip_total: eff.skip_total,
        filecount: eff.filecount,
        filetime: eff.filetime,
        output_format: eff.output_format.clone(),
        terminal_width,
        use_colors,
    }
}
RS"}

