use std::io::{BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};

use cli::FileTimeKind;
use regex_engine::Regex;
use sizefmt::OutputFormat;
use tree::{BuildCtx, BuildOpts, ProgressShared, Node, TimeFilters, TimeCond};

struct Effective {
    depth: Option<usize>,
    threads: Option<usize>,
    number_of_lines: Option<usize>,
    full_paths: bool,
    ignore_directory: Vec<PathBuf>,
    ignore_all_in_file: Option<String>,
    dereference_links: bool,
    limit_filesystem: bool,
    apparent_size: bool,
    reverse: bool,
    no_colors: bool,
    force_colors: bool,
    no_percent_bars: bool,
    bars_on_right: bool,
    min_size: Option<u64>,
    min_size_present: bool,
    screen_reader: bool,
    skip_total: bool,
    filecount: bool,
    ignore_hidden: bool,
    invert_filter: Vec<String>,
    filter: Vec<String>,
    file_types: bool,
    terminal_width: Option<usize>,
    no_progress: bool,
    print_errors: bool,
    only_dir: bool,
    only_file: bool,
    output_format: OutputFormat,
    stack_size: Option<usize>,
    output_json: bool,
    mtime: Option<String>,
    atime: Option<String>,
    ctime: Option<String>,
    files0_from: Option<String>,
    files_from: Option<String>,
    collapse: Vec<PathBuf>,
    filetime: Option<FileTimeKind>,
}

fn main() {
    let (cli, _state) = cli::parse_cli();
    // Load config
    let cfg = config_file::load_config(cli.config.as_deref());

    // Merge effective options
    let mut eff = Effective {
        depth: cli.depth.or(cfg.depth),
        threads: cli.threads.or(cfg.threads),
        number_of_lines: cli.number_of_lines.or(cfg.number_of_lines),
        full_paths: cli.full_paths || cfg.display_full_paths,
        ignore_directory: cli.ignore_directory.iter().map(|s| PathBuf::from(s)).collect(),
        ignore_all_in_file: cli.ignore_all_in_file.clone(),
        dereference_links: cli.dereference_links,
        limit_filesystem: cli.limit_filesystem,
        apparent_size: cli.apparent_size || cfg.display_apparent_size,
        reverse: cli.reverse || cfg.reverse,
        no_colors: cli.no_colors || cfg.no_colors,
        force_colors: cli.force_colors || cfg.force_colors,
        no_percent_bars: cli.no_percent_bars || cfg.no_bars,
        bars_on_right: cli.bars_on_right || cfg.bars_on_right,
        min_size: None,
        min_size_present: false,
        screen_reader: cli.screen_reader || cfg.screen_reader,
        skip_total: cli.skip_total || cfg.skip_total,
        filecount: cli.filecount,
        ignore_hidden: cli.ignore_hidden || cfg.ignore_hidden,
        invert_filter: cli.invert_filter.clone(),
        filter: cli.filter.clone(),
        file_types: cli.file_types,
        terminal_width: cli.terminal_width,
        no_progress: cli.no_progress,
        print_errors: cli.print_errors || cfg.print_errors,
        only_dir: cli.only_dir || cfg.only_dir,
        only_file: cli.only_file || cfg.only_file,
        output_format: if let Some(f) = cli.output_format.clone() { f } else if let Some(s) = cfg.output_format.as_deref() { sizefmt::parse_config_output_format(s) } else { OutputFormat::Binary },
        stack_size: cli.stack_size.or(cfg.stack_size),
        output_json: cli.output_json || cfg.output_json,
        mtime: cli.mtime.clone(),
        atime: cli.atime.clone(),
        ctime: cli.ctime.clone(),
        files0_from: cli.files0_from.clone().or(cfg.files0_from.clone()),
        files_from: cli.files_from.clone().or(cfg.files_from.clone()),
        collapse: cli.collapse.iter().map(|s| PathBuf::from(s)).collect(),
        filetime: cli.filetime,
    };
    let min_size_string: Option<String> = cli.min_size.clone().or(cfg.min_size.clone());
    if let Some(s) = &min_size_string {
        eff.min_size = sizefmt::parse_min_size(s);
        eff.min_size_present = eff.min_size.is_some();
    }

    // Determine target paths (files-from handling happens before regex errors)
    let targets: Vec<String> = determine_targets(&cli, &eff);

    // Compile regexes (CLI filter / invert)
    let mut filter_res: Vec<Regex> = Vec::new();
    for pat in &eff.filter {
        match Regex::new(pat) {
            Ok(r) => filter_res.push(r),
            Err(e) => {
                eprintln!("Ignoring bad value for regex {}", e.render_debug(pat));
                std::process::exit(1);
            }
        }
    }
    let mut invert_res: Vec<Regex> = Vec::new();
    for pat in &eff.invert_filter {
        match Regex::new(pat) {
            Ok(r) => invert_res.push(r),
            Err(e) => {
                eprintln!("Ignoring bad value for regex {}", e.render_debug(pat));
                std::process::exit(1);
            }
        }
    }

    // Read ignore-all-in-file (panics like original on read errors, main thread)
    if let Some(file_path) = &eff.ignore_all_in_file {
        read_ignore_file(file_path, &mut invert_res);
    }

    // Time filters parse (panics main thread on invalid)
    let mtime_cond = parse_time_opt(&eff.mtime);
    let atime_cond = parse_time_opt(&eff.atime);
    let ctime_cond = parse_time_opt(&eff.ctime);
    let time_filters = TimeFilters::new(mtime_cond, atime_cond, ctime_cond);

    // Spawn worker thread with stack size
    let stack_size = eff.stack_size;
    let output_format_for_worker = eff.output_format.clone();
    // Move needed data into worker
    let worker = move || -> i32 {
        run_worker(eff, targets, filter_res, invert_res, time_filters)
    };
    let builder = std::thread::Builder::new();
    let builder = match stack_size {
        Some(s) if s > 0 => builder.stack_size(s),
        _ => builder.stack_size(1_073_741_824),
    };
    match builder.spawn(worker) {
        Ok(handle) => {
            match handle.join() {
                Ok(code) => std::process::exit(code),
                Err(_) => std::process::exit(101),
            }
        }
        Err(e) => {
            eprintln!("Problem initializing rayon, try: export RAYON_NUM_THREADS=1");
            eprintln!();
            progress::panic_exit("main", "src/main.rs:467:13", &e.to_string());
        }
    }
}

fn parse_time_opt(v: &Option<String>) -> Option<TimeCond> {
    match v {
        None => None,
        Some(s) => {
            match tree::parse_time_cond(s) {
                Ok(c) => Some(c),
                Err(_) => {
                    progress::panic_exit("main", "src/config.rs:203:41", "invalid data format");
                }
            }
        }
    }
}

fn read_ignore_file(path_str: &str, invert: &mut Vec<Regex>) {
    // Emulates File::open(...).unwrap() / lines().unwrap() panics at src/main.rs:184:14
    let file = match std::fs::File::open(path_str) {
        Ok(f) => f,
        Err(e) => {
            progress::panic_exit("main", "src/main.rs:184:14", &format!("called `Result::unwrap()` on an `Err` value: {:?}", e));
        }
    };
    let reader = BufReader::new(file);
    for line_res in reader.lines() {
        match line_res {
            Ok(line) => {
                if let Ok(r) = Regex::new(&line) {
                    invert.push(r);
                }
            }
            Err(e) => {
                progress::panic_exit("main", "src/main.rs:184:14", &format!("called `Result::unwrap()` on an `Err` value: {:?}", e));
            }
        }
    }
}

fn determine_targets(cli: &cli::Cli, eff: &Effective) -> Vec<String> {
    if let Some(f0) = &eff.files0_from {
        return read_paths_from_source(f0, true);
    }
    if let Some(f) = &eff.files_from {
        return read_paths_from_source(f, false);
    }
    if !cli.paths.is_empty() {
        return cli.paths.clone();
    }
    vec![".".to_string()]
}

fn read_paths_from_source(source: &str, nul: bool) -> Vec<String> {
    if source == "-" {
        // read stdin to string; on error/UTF-8 -> empty
        let mut buf = String::new();
        let ok = std::io::stdin().read_to_string(&mut buf).is_ok();
        let paths: Vec<String> = if !ok {
            Vec::new()
        } else if nul {
            buf.split('\0').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect()
        } else {
            buf.lines().map(|s| s.to_string()).collect()
        };
        if paths.is_empty() {
            eprintln!("No files provided, defaulting to current directory");
            return vec![".".to_string()];
        }
        return paths;
    }
    match std::fs::read_to_string(source) {
        Ok(content) => {
            if nul {
                content.split('\0').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect()
            } else {
                content.lines().map(|s| s.to_string()).collect()
            }
        }
        Err(e) => {
            eprintln!("Failed to read file: {}", e);
            vec![".".to_string()]
        }
    }
}

fn run_worker(
    eff: Effective,
    targets: Vec<String>,
    filter_res: Vec<Regex>,
    invert_res: Vec<Regex>,
    time_filters: TimeFilters,
) -> i32 {
    // Progress
    let progress = progress::Progress::start(!eff.no_progress, eff.output_format.clone());
    let shared: std::sync::Arc<ProgressShared> = progress.shared();

    let build_opts = BuildOpts {
        apparent: eff.apparent_size,
        deref: eff.dereference_links,
        limit_fs: eff.limit_filesystem,
        filecount: eff.filecount,
        filetime: eff.filetime,
        filters: filter_res,
        invert_filters: invert_res,
        time_filters,
        ignore_hidden: eff.ignore_hidden,
        ignore_directories: eff.ignore_directory.clone(),
    };
    let mut ctx = BuildCtx { opts: build_opts, bad_paths: Vec::new(), perm_paths: Vec::new(), progress: Some(shared.clone()) };

    // Dedup input paths (PathBuf equality, preserve first)
    let mut deduped_targets: Vec<PathBuf> = Vec::new();
    for t in &targets {
        let p = PathBuf::from(t);
        if !deduped_targets.contains(&p) {
            deduped_targets.push(p);
        }
    }

    // Build roots, with depth + collapse per-root
    let targets_empty = deduped_targets.is_empty();
    let mut root_nodes: Vec<Node> = Vec::new();
    for target in &deduped_targets {
        if let Some(mut node) = tree::build_root(&mut ctx, target) {
            // depth prune per root
            tree::prune_depth(&mut node, eff.depth);
            // collapse per root
            let root_path = tree::normalize_path(target);
            tree::collapse_tree(&mut node, &root_path, &eff.collapse);
            root_nodes.push(node);
        }
    }

    // If all targets failed to produce a node (and there were targets), errors will be printed and exit 1
    let all_failed = root_nodes.is_empty() && !targets_empty;

    // Combine into a top tree
    let mut top: Node;
    let is_total: bool;
    if root_nodes.len() == 1 {
        top = root_nodes.into_iter().next().unwrap();
        is_total = false;
    } else {
        is_total = true;
        let children = root_nodes;
        let total_size = tree::aggregate_size(eff.filetime, 0, &children);
        let mut t = Node::new(PathBuf::from("(total)"), total_size, 0);
        t.children = children;
        // (total) children are already sorted? Root nodes were built in input order.
        // Sort total's children descending for display/JSON
        t.children.sort_by(tree::node_cmp_desc);
        top = t;
        // reassign total size (aggregation unaffected by order)
        top.size = total_size;
    }

    if all_failed {
        progress.stop();
        if !ctx.bad_paths.is_empty() {
            eprintln!("No such file or directory: {}", ctx.bad_paths.join(", "));
        }
        // permission errors unlikely, but print after
        print_perm_errors(&ctx, &eff);
        return 1;
    }

    // dedup hardlinks (post-process) across whole tree
    tree::dedup_tree(&mut top, eff.apparent_size, eff.filetime);

    // duplicate root renaming (only for total, not full paths)
    if is_total && !eff.full_paths {
        tree::rename_duplicate_roots(&mut top);
    }

    // Terminal detection for later display options (height/width/colors)
    let detected_term = term::terminal_size();

    // Effective number of lines
    let effective_lines: usize = if let Some(n) = eff.number_of_lines {
        n
    } else {
        let height: usize = detected_term.map(|(_, rows)| rows as usize).unwrap_or(24);
        std::cmp::max(20usize, height.saturating_sub(10))
    };

    // File-types path
    let final_tree: Node;
    if eff.file_types {
        let mut ft = tree::aggregate_file_types(&top, is_total, effective_lines, eff.filetime, eff.filecount);
        if eff.only_file {
            tree::only_file_tree(&mut ft);
        }
        if eff.only_dir {
            tree::only_dir_tree(&mut ft);
        }
        final_tree = ft;
    } else {
        let mut t = top;
        if eff.only_file {
            tree::only_file_tree(&mut t);
        }
        if eff.only_dir {
            tree::only_dir_tree(&mut t);
        }
        if eff.min_size_present {
            if let Some(min) = eff.min_size {
                tree::prune_min_size(&mut t, min);
            }
        }
        // selection
        let selected = tree::select_tree(&t, effective_lines);
        final_tree = selected;
    }

    progress.stop();

    // Error messages before output
    let has_bad = !ctx.bad_paths.is_empty();
    if has_bad {
        eprintln!("No such file or directory: {}", ctx.bad_paths.join(", "));
    }
    print_perm_errors(&ctx, &eff);
    if has_bad && final_tree.children.is_empty() {
        return 1;
    }

    // Output
    if eff.output_json {
        let display_opts = make_display_opts(&eff, detected_term);
        match display::node_to_json_string(&final_tree, &display_opts) {
            Ok(s) => {
                println!("{}", s);
                0
            }
            Err(_) => {
                progress::panic_exit("<unnamed>", "src/main.rs:328:53", "called `Result::unwrap()` on an `Err` value: Error(\"path contains invalid UTF-8 characters\", line: 0, column: 0)");
            }
        }
    } else {
        let display_opts = make_display_opts(&eff, detected_term);
        display::display_tree(&final_tree, &display_opts);
        0
    }
}

fn print_perm_errors(ctx: &BuildCtx, eff: &Effective) {
    if ctx.perm_paths.is_empty() { return; }
    if eff.print_errors {
        eprintln!("Did not have permissions for directories: {}", ctx.perm_paths.join(", "));
    } else {
        eprintln!("Did not have permissions for all directories (add --print-errors to see errors)");
    }
}

fn make_display_opts(eff: &Effective, detected_term: Option<(u16, u16)>) -> display::DisplayOpts {
    let terminal_width: usize = if let Some(w) = eff.terminal_width {
        w
    } else if let Some((cols, _)) = detected_term {
        cols as usize
    } else {
        80
    };
    let use_colors = if eff.force_colors {
        true
    } else if eff.no_colors {
        false
    } else if std::env::var_os("NO_COLOR").is_some() {
        false
    } else {
        detected_term.is_some()
    };
    display::DisplayOpts {
        reverse: eff.reverse,
        full_paths: eff.full_paths,
        no_percent_bars: eff.no_percent_bars,
        bars_on_right: eff.bars_on_right,
        screen_reader: eff.screen_reader,
        skip_total: eff.skip_total,
        filecount: eff.filecount,
        filetime: eff.filetime,
        output_format: eff.output_format.clone(),
        terminal_width,
        use_colors,
    }
}
RS

