        fails.append(args)
        print("DIFF",args,"rc",a.returncode,b.returncode,"cwd",cwd,"env",extra_env)
        if norm(a.stdout)!=norm(b.stdout): print(" orig out",a.stdout[:400]); print(" new out",b.stdout[:400])
