for z in ["0","1","10","999","1K","1KB","1KiB","1M","1MB","10KB","10KIB","5e3","10X","1,000","10.5","+10K","10KK","10KZ","0x10"]:
    check(["-P","-c","-s","-z",z,"/tmp/fixmin"])
for w in ["8","12","14","15","16","20","22","23","30","33","40","80","200"]:
    check(["-P","-c","-s","-w",w,"/tmp/fix1"])
    check(["-P","-c","-s","-w",w,"-r","/tmp/fix1"])
for fmt in ["si","b","k","m","g","t","kb","mb","gb","tb","kib","SI","B"]:
