        // chars[pos] == '{'
        let start = self.pos;
        self.pos += 1; // '{'
        // First decimal
        if self.pos >= self.chars.len() {
            return Err(self.error(start, self.pos - start, "unclosed counted repetition"));
        }
        if !self.chars[self.pos].is_ascii_digit() {
            return Err(self.error(self.pos, 1, "repetition quantifier expects a valid decimal"));
        }
        let num_start = self.pos;
        let mut digits = String::new();
        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
            digits.push(self.chars[self.pos]);
            self.pos += 1;
        }
        let min: u32 = match digits.parse::<u64>() {
            Ok(v) if v <= u32::MAX as u64 => v as u32,
            _ => return Err(self.error(num_start, digits.chars().count(), "decimal literal invalid")),
        };
        if self.pos >= self.chars.len() {
            return Err(self.error(start, self.pos - start, "unclosed counted repetition"));
        }
        match self.chars[self.pos] {
            '}' => {
                self.pos += 1;
                let _ = self.eat_lazy();
                Ok(Some(Ast::Repeat { node: Box::new(node), min, max: Some(min) }))
            }
            ',' => {
                self.pos += 1;
                if self.pos >= self.chars.len() {
                    return Err(self.error(start, self.pos - start, "unclosed counted repetition"));
                }
                if self.chars[self.pos] == '}' {
                    self.pos += 1;
                    let _ = self.eat_lazy();
                    return Ok(Some(Ast::Repeat { node: Box::new(node), min, max: None }));
                }
                if !self.chars[self.pos].is_ascii_digit() {
                    return Err(self.error(self.pos, 1, "repetition quantifier expects a valid decimal"));
                }
                let num2_start = self.pos;
                let mut digits2 = String::new();
                while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                    digits2.push(self.chars[self.pos]);
                    self.pos += 1;
                }
                let max: u32 = match digits2.parse::<u64>() {
                    Ok(v) if v <= u32::MAX as u64 => v as u32,
                    _ => return Err(self.error(num2_start, digits2.chars().count(), "decimal literal invalid")),
                };
                if self.pos >= self.chars.len() {
                    return Err(self.error(start, self.pos - start, "unclosed counted repetition"));
                }
                if self.chars[self.pos] != '}' {
                    return Err(self.error(start, self.pos - start, "unclosed counted repetition"));
                }
                if min > max {
                    return Err(self.error(start, self.pos - start + 1, "invalid repetition count range, the start must be <= the end"));
                }
                self.pos += 1;
                let _ = self.eat_lazy();
                Ok(Some(Ast::Repeat { node: Box::new(node), min, max: Some(max) }))
            }
            _ => {
                Err(self.error(start, self.pos - start, "unclosed counted repetition"))
            }
        }
    }

