        "c"|"other"|"cc"|"control"|"cntrl"|"cf"|"format"|"co"|"privateuse"|"cs"|"surrogate"|"cn"|"unassigned"|
        "alphabetic"|"alpha"|"lowercase"|"upper"|"uppercase"|"whitespace"|"whitespace2"|"alphanumeric"|
        "ascii"|"any"|"assigned"|
        // scripts
        "greek"|"cyrillic"|"han"|"hiragana"|"katakana"|"hebrew"|"arabic"|"latin"|"armenian"|"georgian"|
        "hangul"|"thai"|"devanagari"|"bopomofo"|"ethiopic"|"mongolian"|"tamil"|"telugu"|"kannada"|
        "malayalam"|"gujarati"|"gurmukhi"|"bengali"|"oriya"|"myanmar"|"khmer"|"lao"|"tibetan"|
        "cherokee"|"canadianaboriginal"|"ogham"|"runic"|"syriac"|"thaana"|"sinhala"|"yi"|"mongolian2"
    ) || n == "white" || n == "wspace"
}

fn property_matches(name: &str, c: char) -> bool {
    let cp = c as u32;
    match name {
        "l"|"letter" => c.is_alphabetic(),
        "lu"|"uppercaseletter"|"upper"|"uppercase" => c.is_uppercase(),
        "ll"|"lowercaseletter"|"lowercase" => c.is_lowercase(),
        "lt"|"titlecaseletter" => c.is_uppercase(),
        "lm"|"modifierletter" => false,
        "lo"|"otherletter" => c.is_alphabetic() && !c.is_lowercase() && !c.is_uppercase(),
        "m"|"mark"|"mn"|"nonspacingmark"|"mc"|"spacingmark"|"me"|"enclosingmark" => is_combining_mark(c),
        "n"|"number" => c.is_numeric(),
        "nd"|"decimalnumber" => c.is_numeric(),
        "nl"|"letternumber" => false,
        "no"|"othernumber" => c.is_numeric(),
        "p"|"punctuation"|"punct"|"po"|"otherpunctuation" => is_punct_char(c),
        "pc"|"connectorpunctuation" => c == '_' || is_punct_char(c),
        "pd"|"dashpunctuation" => matches!(c, '-'|'\\u{2010}'..='\\u{2015}'),
        "ps"|"openpunctuation" => matches!(c, '('|'['|'{'|'<'|'\\u{2018}'|'\\u{201C}'),
        "pe"|"closepunctuation" => matches!(c, ')'|']'|'}'|'>'|'\\u{2019}'|'\\u{201D}'),
        "pi"|"initialpunctuation" => matches!(c, '\\u{2018}'|'\\u{201C}'|'\\u{201A}'|'\\u{201E}'),
        "pf"|"finalpunctuation" => matches!(c, '\\u{2019}'|'\\u{201D}'),
        "s"|"symbol"|"sm"|"mathsymbol"|"sc"|"currencysymbol"|"sk"|"modifiersymbol"|"so"|"othersymbol" => {
            !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control() && !is_punct_char(c)
        }
        "z"|"separator"|"zs"|"spaceseparator" => c.is_whitespace(),
        "zl"|"lineseparator" => c == '\\u{2028}',
        "zp"|"paragraphseparator" => c == '\\u{2029}',
        "c"|"other"|"cc"|"control"|"cntrl" => c.is_control(),
        "cf"|"format" => matches!(cp, 0x200b..=0x200f | 0x202a..=0x202e | 0x2060..=0x2064 | 0xfeff),
        "co"|"privateuse" => matches!(cp, 0xe000..=0xf8ff | 0xf0000..=0xffffd | 0x100000..=0x10fffd),
        "cs"|"surrogate" => false,
        "cn"|"unassigned" => false,
        "alphabetic"|"alpha" => c.is_alphabetic(),
        "alphanumeric" => c.is_alphanumeric(),
        "whitespace"|"white" => c.is_whitespace(),
        "ascii"|"any" => c.is_ascii(),
        "assigned" => true,
        "greek" => matches!(cp, 0x370..=0x3ff | 0x1f00..=0x1fff),
        "cyrillic" => matches!(cp, 0x400..=0x4ff | 0x500..=0x52f | 0x2de0..=0x2dff),
        "han" => matches!(cp, 0x4e00..=0x9fff | 0x3400..=0x4dbf | 0x20000..=0x2a6df),
        "hiragana" => matches!(cp, 0x3040..=0x309f | 0x1b001..=0x1b11f),
        "katakana" => matches!(cp, 0x30a0..=0x30ff | 0x31f0..=0x31ff),
        "hebrew" => matches!(cp, 0x590..=0x5ff),
        "arabic" => matches!(cp, 0x600..=0x6ff | 0x750..=0x77f | 0x8a0..=0x8ff),
        "latin" => matches!(cp, 0x41..=0x5a | 0x61..=0x7a | 0xc0..=0xff | 0x100..=0x24f | 0x1e00..=0x1eff) && c != '×' && c != '÷',
        "armenian" => matches!(cp, 0x530..=0x58f),
        "georgian" => matches!(cp, 0x10a0..=0x10ff | 0x2d00..=0x2d2f),
        "hangul" => matches!(cp, 0xac00..=0xd7a3 | 0x1100..=0x11ff | 0x3130..=0x318f),
        "thai" => matches!(cp, 0xe00..=0xe7f),
        "devanagari" => matches!(cp, 0x900..=0x97f),
        "bopomofo" => matches!(cp, 0x3100..=0x312f),
        "ethiopic" => matches!(cp, 0x1200..=0x137f),
        "mongolian"|"mongolian2" => matches!(cp, 0x1800..=0x18af),
        "tamil" => matches!(cp, 0xb80..=0xbff),
        "telugu" => matches!(cp, 0xc00..=0xc7f),
        "kannada" => matches!(cp, 0xc80..=0xcff),
        "malayalam" => matches!(cp, 0xd00..=0xd7f),
        "gujarati" => matches!(cp, 0xa80..=0xaff),
        "gurmukhi" => matches!(cp, 0xa00..=0xa7f),
        "bengali" => matches!(cp, 0x980..=0x9ff),
        "oriya" => matches!(cp, 0xb00..=0xb7f),
        "myanmar" => matches!(cp, 0x1000..=0x109f),
        "khmer" => matches!(cp, 0x1780..=0x17ff),
        "lao" => matches!(cp, 0xe80..=0xeff),
        "tibetan" => matches!(cp, 0xf00..=0xfff),
        "cherokee" => matches!(cp, 0x13a0..=0x13ff),
        "canadianaboriginal" => matches!(cp, 0x1400..=0x167f),
        "ogham" => matches!(cp, 0x1680..=0x169f),
        "runic" => matches!(cp, 0x16a0..=0x16ff),
        "syriac" => matches!(cp, 0x700..=0x74f),
        "thaana" => matches!(cp, 0x780..=0x7bf),
        "sinhala" => matches!(cp, 0xd80..=0xdff),
        "yi" => matches!(cp, 0xa000..=0xa48f),
        _ => false,
    }
}

fn is_combining_mark(c: char) -> bool {
    let cp = c as u32;
    matches!(cp, 0x300..=0x36f | 0x483..=0x489 | 0x591..=0x5bd | 0x610..=0x61a | 0x64b..=0x65f |
        0x20d0..=0x20f0 | 0xfe20..=0xfe2f | 0xfe00..=0xfe0f)
}

fn is_punct_char(c: char) -> bool {
    c.is_ascii_punctuation() || matches!(c as u32, 0x2010..=0x2027 | 0x2030..=0x205e | 0x3001..=0x3003 | 0x3008..=0x3011 | 0xff01..=0xff0f)
}

